/// Raven `DeathFX`.
///
/// Raven: team no longer indicates species/race.  NPC_class should be used to
/// identify certain npc types.
/// Source: `oracle/codemp/game/g_combat.c:1883-1984`
pub fn DeathFX(ctx: &mut GameContext, ent: Option<EntityId>) {
    let mut effectPos: vec3_t = [0.0; 3];
    let mut right: vec3_t = [0.0; 3];

    // ent may be an NPC — `.client` is a pool client, deref stays raw (2b).
    let client = ent.map_or(core::ptr::null_mut(), |id| ctx.entity(id).client);
    if ent.is_none() || client.is_null() {
        return;
    }
    let ent = ent.unwrap();

    let defaultDir: vec3_t = [0.0, 0.0, 1.0];
    let npc_class = unsafe { (*client).NPC_class };

    match npc_class {
        class_t::CLASS_MOUSE => {
            crate::q_math::_VectorCopy(ctx.entity(ent).r.currentOrigin, &mut effectPos);
            effectPos[2] -= 20.0;
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("env/small_explode").as_ptr()),
                effectPos,
                defaultDir,
            );
            crate::g_utils::G_Sound(
                ctx,
                Some(ent),
                CHAN_AUTO,
                crate::g_utils::G_SoundIndex(cstr("sound/chars/mouse/misc/death1").as_ptr()),
            );
        }
        class_t::CLASS_PROBE => {
            crate::q_math::_VectorCopy(ctx.entity(ent).r.currentOrigin, &mut effectPos);
            effectPos[2] += 50.0;
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("explosions/probeexplosion1").as_ptr()),
                effectPos,
                defaultDir,
            );
        }
        class_t::CLASS_ATST => {
            AngleVectors(
                ctx.entity(ent).r.currentAngles,
                None,
                Some(&mut right),
                None,
            );
            crate::q_math::_VectorMA(ctx.entity(ent).r.currentOrigin, 20.0, right, &mut effectPos);
            effectPos[2] += 180.0;
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("explosions/droidexplosion1").as_ptr()),
                effectPos,
                defaultDir,
            );
            crate::q_math::_VectorMA(effectPos, -40.0, right, &mut effectPos);
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("explosions/droidexplosion1").as_ptr()),
                effectPos,
                defaultDir,
            );
        }
        class_t::CLASS_SEEKER | class_t::CLASS_REMOTE => {
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("env/small_explode").as_ptr()),
                ctx.entity(ent).r.currentOrigin,
                defaultDir,
            );
        }
        class_t::CLASS_GONK => {
            crate::q_math::_VectorCopy(ctx.entity(ent).r.currentOrigin, &mut effectPos);
            effectPos[2] -= 5.0;
            let s = format!(
                "sound/chars/gonk/misc/death{}.wav",
                ctx.world.bg_state.rng.Q_irand(1, 3)
            );
            crate::g_utils::G_Sound(
                ctx,
                Some(ent),
                CHAN_AUTO,
                crate::g_utils::G_SoundIndex(cstr(&s).as_ptr()),
            );
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("env/med_explode").as_ptr()),
                effectPos,
                defaultDir,
            );
        }
        // should list all remaining droids here, hope I didn't miss any
        class_t::CLASS_R2D2 => {
            crate::q_math::_VectorCopy(ctx.entity(ent).r.currentOrigin, &mut effectPos);
            effectPos[2] -= 10.0;
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("env/med_explode").as_ptr()),
                effectPos,
                defaultDir,
            );
            crate::g_utils::G_Sound(
                ctx,
                Some(ent),
                CHAN_AUTO,
                crate::g_utils::G_SoundIndex(cstr("sound/chars/mark2/misc/mark2_explo").as_ptr()),
            );
        }
        class_t::CLASS_PROTOCOL | class_t::CLASS_R5D2 => {
            crate::q_math::_VectorCopy(ctx.entity(ent).r.currentOrigin, &mut effectPos);
            effectPos[2] -= 10.0;
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("env/med_explode").as_ptr()),
                effectPos,
                defaultDir,
            );
            crate::g_utils::G_Sound(
                ctx,
                Some(ent),
                CHAN_AUTO,
                crate::g_utils::G_SoundIndex(cstr("sound/chars/mark2/misc/mark2_explo").as_ptr()),
            );
        }
        class_t::CLASS_MARK2 => {
            crate::q_math::_VectorCopy(ctx.entity(ent).r.currentOrigin, &mut effectPos);
            effectPos[2] -= 15.0;
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("explosions/droidexplosion1").as_ptr()),
                effectPos,
                defaultDir,
            );
            crate::g_utils::G_Sound(
                ctx,
                Some(ent),
                CHAN_AUTO,
                crate::g_utils::G_SoundIndex(cstr("sound/chars/mark2/misc/mark2_explo").as_ptr()),
            );
        }
        class_t::CLASS_INTERROGATOR => {
            crate::q_math::_VectorCopy(ctx.entity(ent).r.currentOrigin, &mut effectPos);
            effectPos[2] -= 15.0;
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("explosions/droidexplosion1").as_ptr()),
                effectPos,
                defaultDir,
            );
            crate::g_utils::G_Sound(
                ctx,
                Some(ent),
                CHAN_AUTO,
                crate::g_utils::G_SoundIndex(
                    cstr("sound/chars/interrogator/misc/int_droid_explo").as_ptr(),
                ),
            );
        }
        class_t::CLASS_MARK1 => {
            AngleVectors(
                ctx.entity(ent).r.currentAngles,
                None,
                Some(&mut right),
                None,
            );
            crate::q_math::_VectorMA(ctx.entity(ent).r.currentOrigin, 10.0, right, &mut effectPos);
            effectPos[2] -= 15.0;
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("explosions/droidexplosion1").as_ptr()),
                effectPos,
                defaultDir,
            );
            crate::q_math::_VectorMA(effectPos, -20.0, right, &mut effectPos);
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("explosions/droidexplosion1").as_ptr()),
                effectPos,
                defaultDir,
            );
            crate::q_math::_VectorMA(effectPos, -20.0, right, &mut effectPos);
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("explosions/droidexplosion1").as_ptr()),
                effectPos,
                defaultDir,
            );
            crate::g_utils::G_Sound(
                ctx,
                Some(ent),
                CHAN_AUTO,
                crate::g_utils::G_SoundIndex(cstr("sound/chars/mark1/misc/mark1_explo").as_ptr()),
            );
        }
        class_t::CLASS_SENTRY => {
            crate::g_utils::G_Sound(
                ctx,
                Some(ent),
                CHAN_AUTO,
                crate::g_utils::G_SoundIndex(cstr("sound/chars/sentry/misc/sentry_explo").as_ptr()),
            );
            crate::q_math::_VectorCopy(ctx.entity(ent).r.currentOrigin, &mut effectPos);
            crate::g_utils::G_PlayEffectID(
                crate::g_utils::G_EffectIndex(cstr("env/med_explode").as_ptr()),
                effectPos,
                defaultDir,
            );
        }
        _ => {}
    }
}

/// Raven `G_CheckVictoryScript`.
///
/// Source: `oracle/codemp/game/g_combat.c:1986-2014`
pub fn G_CheckVictoryScript(ctx: &mut GameContext, self_: EntityId) {
    // self_'s `.NPC` (gNPC_t) and `.client` (pool) pointers deref raw (traps
    // 2b/2c); the body keeps one unsafe scope. Entity fields route through the
    // accessor.
    unsafe {
        if G_ActivateBehavior(ctx, Some(self_), bSet_t::BSET_VICTORY as c_int) != qfalse {
            return;
        }

        let npc = ctx.entity(self_).NPC;
        let client = ctx.entity(self_).client;

        if !npc.is_null() && ctx.entity(self_).s.weapon == WP_SABER as c_int {
            // Jedi taunt from within their AI
            (*npc).blockedSpeechDebounceTime = 0; // get them ready to taunt
            return;
        }
        if !client.is_null() && (*client).NPC_class == class_t::CLASS_GALAKMECH {
            ctx.entity_mut(self_).wait = 1.0;
            let self_eid = Some(self_);
            let gloat_time = ctx.world.bg_state.rng.Q_irand(5000, 8000);
            TIMER_Set(ctx, self_eid, c"gloatTime".as_ptr(), gloat_time);
            (*npc).blockedSpeechDebounceTime = 0; // get him ready to taunt
            return;
        }
        // FIXME: any way to not say this *right away*?
        let level_time = ctx.world.level.time;
        if !npc.is_null()
            && !(*npc).group.is_null()
            && !(*(*npc).group).commander.is_null()
            && !((*(*(*npc).group).commander).NPC).is_null()
            && (*((*(*(*npc).group).commander).NPC)).rank > (*npc).rank
            && ctx.world.bg_state.rng.Q_irand(0, 2) == 0
        {
            // sometimes have the group commander speak instead
            let cmdr_npc = (*(*(*npc).group).commander).NPC;
            (*cmdr_npc).greetingDebounceTime =
                level_time + ctx.world.bg_state.rng.Q_irand(2000, 5000);
        } else if !npc.is_null() {
            (*npc).greetingDebounceTime = level_time + ctx.world.bg_state.rng.Q_irand(2000, 5000);
        }
    }
}

/// Raven `G_AddPowerDuelScore`.
///
/// Source: `oracle/codemp/game/g_combat.c:2016-2035`
pub fn G_AddPowerDuelScore(ctx: &mut GameContext, team: c_int, score: c_int) {
    let mut i = 0;
    while i < MAX_CLIENTS as c_int {
        let check = EntityId(i as u32);
        let inuse = ctx.entity(check).inuse;
        // real client slot (i < MAX_CLIENTS); deref raw (trap 2b).
        let checkClient = ctx.entity(check).client;
        if inuse != qfalse
            && !checkClient.is_null()
            && unsafe {
                (*checkClient).pers.connected == CON_CONNECTED
                    && (*checkClient).iAmALoser == qfalse
                    && (*checkClient).ps.stats[statIndex_t::STAT_HEALTH as usize] > 0
                    && (*checkClient).sess.sessionTeam != TEAM_SPECTATOR
                    && (*checkClient).sess.duelTeam as c_int == team
            }
        {
            // found a living client on the specified team
            unsafe {
                (*checkClient).sess.wins += score;
            }
            let number = ctx.entity(check).s.number;
            crate::g_client::ClientUserinfoChanged(ctx, number);
        }
        i += 1;
    }
}

/// Raven `G_AddPowerDuelLoserScore`.
///
/// Source: `oracle/codemp/game/g_combat.c:2037-2055`
pub fn G_AddPowerDuelLoserScore(ctx: &mut GameContext, team: c_int, score: c_int) {
    let mut i = 0;
    while i < MAX_CLIENTS as c_int {
        let check = EntityId(i as u32);
        let inuse = ctx.entity(check).inuse;
        // real client slot (i < MAX_CLIENTS); deref raw (trap 2b).
        let checkClient = ctx.entity(check).client;
        if inuse != qfalse
            && !checkClient.is_null()
            && unsafe {
                (*checkClient).pers.connected == CON_CONNECTED
                    && ((*checkClient).iAmALoser != qfalse
                        || ((*checkClient).ps.stats[statIndex_t::STAT_HEALTH as usize] <= 0
                            && (*checkClient).sess.sessionTeam != TEAM_SPECTATOR))
                    && (*checkClient).sess.duelTeam as c_int == team
            }
        {
            // found a living client on the specified team
            unsafe {
                (*checkClient).sess.losses += score;
            }
            let number = ctx.entity(check).s.number;
            crate::g_client::ClientUserinfoChanged(ctx, number);
        }
        i += 1;
    }
}

/// Raven `G_BroadcastObit`.
///
/// Source: `oracle/codemp/game/g_combat.c:2059-2105`
pub fn G_BroadcastObit(
    ctx: &mut GameContext,
    self_: EntityId,
    inflictor: Option<EntityId>,
    attacker: Option<EntityId>,
    killer: c_int,
    meansOfDeath: c_int,
    wasInVehicle: c_int,
    wasJediMaster: qboolean,
) {
    // `SVF_BROADCAST` resolves via the crate prelude glob (`crate::g_public_consts`).
    // broadcast the death event to everyone
    if ctx.entity(self_).s.eType != entityType_t::ET_NPC as c_int
        && ctx.world.globals.g_noPDuelCheck == 0
    {
        let currentOrigin = ctx.entity(self_).r.currentOrigin;
        let ent = G_TempEntity(ctx, currentOrigin, entity_event_t::EV_OBITUARY as c_int);
        let ent = ctx.entity_id_of(ent).unwrap();
        ctx.entity_mut(ent).s.eventParm = meansOfDeath;
        let self_number = ctx.entity(self_).s.number;
        ctx.entity_mut(ent).s.otherEntityNum = self_number;
        if let Some(attacker) = attacker {
            let n = ctx.entity(attacker).s.number;
            ctx.entity_mut(ent).s.otherEntityNum2 = n;
        } else {
            ctx.entity_mut(ent).s.otherEntityNum2 = killer;
        }
        if let Some(inflictor) = inflictor {
            if Q_stricmp(
                c"vehicle_proj".as_ptr(),
                ctx.entity(inflictor).classname as *const c_char,
            ) == 0
            {
                // a vehicle missile
                ctx.entity_mut(ent).s.eventParm = meansOfDeath_t::MOD_VEHICLE as c_int;
                // store index into g_vehWeaponInfo
                let oe2 = ctx.entity(inflictor).s.otherEntityNum2;
                ctx.entity_mut(ent).s.weapon = oe2 + 1;
                // store generic rocket or blaster type of missile
                let inf_weapon = ctx.entity(inflictor).s.weapon;
                ctx.entity_mut(ent).s.generic1 = inf_weapon;
            }
        }
        if wasInVehicle != 0 && ctx.entity(self_).s.number < MAX_CLIENTS as c_int {
            // target is in a vehicle, store the entnum
            ctx.entity_mut(ent).s.lookTarget = wasInVehicle;
        }
        if let Some(attacker) = attacker {
            if ctx.entity(attacker).s.m_iVehicleNum != 0
                && ctx.entity(attacker).s.number < MAX_CLIENTS as c_int
            {
                let v = ctx.entity(attacker).s.m_iVehicleNum;
                ctx.entity_mut(ent).s.brokenLimbs = v;
            } else if ctx.entity(ent).s.lookTarget != 0
                && Q_stricmp(
                    c"func_rotating".as_ptr(),
                    ctx.entity(attacker).classname as *const c_char,
                ) == 0
            {
                // my vehicle was killed by a func_rotating, probably an asteroid
                ctx.entity_mut(ent).s.saberInFlight = qtrue;
            }
        }
        ctx.entity_mut(ent).r.svFlags = SVF_BROADCAST; // send to everyone
        ctx.entity_mut(ent).s.isJediMaster = wasJediMaster;
    }
}

/// Raven `player_die`.
///
/// Source: `oracle/codemp/game/g_combat.c:2123-3011`
pub fn player_die(
    ctx: &mut GameContext,
    self_: EntityId,
    inflictor: Option<EntityId>,
    attacker: Option<EntityId>,
    damage: c_int,
    meansOfDeath: c_int,
) {
    // STAGE-1: EntityId/Option params (body null-checks inflictor/attacker), raw
    // re-derived verbatim (Stage-2 debt); mega-fn.
    let self_: *mut gentity_t = ctx.entity_mut(self_);
    let inflictor: *mut gentity_t =
        unsafe { crate::ent_id::resolve(ctx.world.g_entities.as_mut_ptr(), inflictor) };
    let mut attacker: *mut gentity_t =
        unsafe { crate::ent_id::resolve(ctx.world.g_entities.as_mut_ptr(), attacker) };
    unsafe {
        let base = ctx.world.g_entities.as_mut_ptr();
        let cl = (*self_).client;
        let mut wasJediMaster: qboolean = qfalse;
        let mut sPMType: c_int = 0;
        let mut wasInVehicle: c_int = 0;
        let mut tempInflictorEnt: *mut gentity_t = inflictor;
        let mut tempInflictor: qboolean = qfalse;
        let mut actualMOD = meansOfDeath;

        if (*cl).ps.pm_type == pmtype_t::PM_DEAD as c_int {
            return;
        }

        if ctx.world.level.intermissiontime != 0 {
            return;
        }

        // check player stuff
        ctx.world.globals.g_dontFrickinCheck = qfalse;

        if ctx.world.cvars.g_gametype.integer == GT_POWERDUEL {
            // don't want to wait til later in the frame if this is the case
            crate::g_main::CheckExitRules(ctx);

            if ctx.world.level.intermissiontime != 0 {
                return;
            }
        }

        let selfVeh = (*self_).m_pVehicle;
        if (*self_).s.eType == entityType_t::ET_NPC as c_int
            && (*self_).s.NPC_class == class_t::CLASS_VEHICLE as c_int
            && !(*self_).m_pVehicle.is_null()
            && (*(*selfVeh).m_pVehicleInfo).explosionDelay == 0
            && (!(*selfVeh).m_pPilot.is_null()
                || (*selfVeh).m_iNumPassengers > 0
                || !(*selfVeh).m_pDroidUnit.is_null())
        {
            // kill everyone on board in the name of the attacker... if the vehicle has no death delay
            let mut murderer: *mut gentity_t = core::ptr::null_mut();
            let mut killEnt: *mut gentity_t;
            let mut i = 0;

            if (*cl).ps.otherKillerTime >= ctx.world.level.time {
                // use the last attacker
                murderer =
                    &mut ctx.world.g_entities[(*cl).ps.otherKiller as usize] as *mut gentity_t;
                if (*murderer).inuse == qfalse || (*murderer).client.is_null() {
                    murderer = core::ptr::null_mut();
                } else {
                    let murdererVeh = (*murderer).m_pVehicle;
                    if (*murderer).s.number >= MAX_CLIENTS as c_int
                        && (*murderer).s.eType == entityType_t::ET_NPC as c_int
                        && (*murderer).s.NPC_class == class_t::CLASS_VEHICLE as c_int
                        && !(*murderer).m_pVehicle.is_null()
                        && !(*murdererVeh).m_pPilot.is_null()
                    {
                        let murderPilot = &mut ctx.world.g_entities
                            [(*((*murdererVeh).m_pPilot as *mut gentity_t)).s.number as usize]
                            as *mut gentity_t;
                        if (*murderPilot).inuse != qfalse && !(*murderPilot).client.is_null() {
                            // give the pilot of the offending vehicle credit for the kill
                            murderer = murderPilot;
                            actualMOD = (*cl).otherKillerMOD;
                            if (*cl).otherKillerVehWeapon > 0 {
                                tempInflictorEnt = crate::g_utils::G_Spawn(ctx);
                                if !tempInflictorEnt.is_null() {
                                    // fake up the inflictor
                                    tempInflictor = qtrue;
                                    (*tempInflictorEnt).classname =
                                        c"vehicle_proj".as_ptr() as *mut c_char;
                                    (*tempInflictorEnt).s.otherEntityNum2 =
                                        (*cl).otherKillerVehWeapon - 1;
                                    (*tempInflictorEnt).s.weapon = (*cl).otherKillerWeaponType;
                                }
                            }
                        }
                    }
                }
            } else if !attacker.is_null()
                && (*attacker).inuse != qfalse
                && !(*attacker).client.is_null()
            {
                let attackerVeh = (*attacker).m_pVehicle;
                if (*attacker).s.number >= MAX_CLIENTS as c_int
                    && (*attacker).s.eType == entityType_t::ET_NPC as c_int
                    && (*attacker).s.NPC_class == class_t::CLASS_VEHICLE as c_int
                    && !(*attacker).m_pVehicle.is_null()
                    && !(*attackerVeh).m_pPilot.is_null()
                {
                    // set vehicles pilot's killer as murderer
                    murderer = &mut ctx.world.g_entities
                        [(*((*attackerVeh).m_pPilot as *mut gentity_t)).s.number as usize]
                        as *mut gentity_t;
                    if (*murderer).inuse != qfalse
                        && !(*murderer).client.is_null()
                        && (*((*murderer).client)).ps.otherKillerTime >= ctx.world.level.time
                    {
                        murderer = &mut ctx.world.g_entities
                            [(*((*murderer).client)).ps.otherKiller as usize]
                            as *mut gentity_t;
                        if (*murderer).inuse == qfalse || (*murderer).client.is_null() {
                            murderer = core::ptr::null_mut();
                        }
                    } else {
                        murderer = core::ptr::null_mut();
                    }
                } else {
                    murderer =
                        &mut ctx.world.g_entities[(*attacker).s.number as usize] as *mut gentity_t;
                }
            } else if !(*selfVeh).m_pPilot.is_null() {
                murderer = (*selfVeh).m_pPilot as *mut gentity_t;
                if (*murderer).inuse == qfalse || (*murderer).client.is_null() {
                    murderer = core::ptr::null_mut();
                }
            }

            // no valid murderer.. just use self I guess
            if murderer.is_null() {
                if attacker.is_null() {
                    murderer = self_;
                } else {
                    murderer = attacker;
                }
            }

            if (*(*selfVeh).m_pVehicleInfo).hideRider != qfalse {
                // pilot is *inside* me, so kill him, too
                killEnt = (*selfVeh).m_pPilot as *mut gentity_t;
                if !killEnt.is_null() && (*killEnt).inuse != qfalse && !(*killEnt).client.is_null()
                {
                    G_Damage(
                        ctx,
                        ctx.entity_id_of(killEnt),
                        ctx.entity_id_of(tempInflictorEnt),
                        ctx.entity_id_of(murderer),
                        None,
                        (*((*killEnt).client)).ps.origin,
                        99999,
                        DAMAGE_NO_PROTECTION,
                        actualMOD,
                    );
                }
                if !(*selfVeh).m_pVehicleInfo.is_null() {
                    let numPass = (*selfVeh).m_iNumPassengers;
                    i = 0;
                    while i < numPass && (*selfVeh).m_iNumPassengers != 0 {
                        // go through and eject the last passenger
                        killEnt = (*selfVeh).m_ppPassengers
                            [((*selfVeh).m_iNumPassengers - 1) as usize]
                            as *mut gentity_t;
                        if !killEnt.is_null() {
                            crate::veh_dispatch::eject(
                                ctx,
                                selfVeh,
                                killEnt as *mut bgEntity_t,
                                qtrue,
                            );
                            if (*killEnt).inuse != qfalse && !(*killEnt).client.is_null() {
                                G_Damage(
                                    ctx,
                                    ctx.entity_id_of(killEnt),
                                    ctx.entity_id_of(tempInflictorEnt),
                                    ctx.entity_id_of(murderer),
                                    None,
                                    (*((*killEnt).client)).ps.origin,
                                    99999,
                                    DAMAGE_NO_PROTECTION,
                                    actualMOD,
                                );
                            }
                        }
                        i += 1;
                    }
                }
            }
            killEnt = (*selfVeh).m_pDroidUnit as *mut gentity_t;
            if !killEnt.is_null() && (*killEnt).inuse != qfalse && !(*killEnt).client.is_null() {
                (*killEnt).flags &= !FL_UNDYING;
                G_Damage(
                    ctx,
                    ctx.entity_id_of(killEnt),
                    ctx.entity_id_of(tempInflictorEnt),
                    ctx.entity_id_of(murderer),
                    None,
                    (*((*killEnt).client)).ps.origin,
                    99999,
                    DAMAGE_NO_PROTECTION,
                    actualMOD,
                );
            }
            if tempInflictor != qfalse {
                crate::g_utils::G_FreeEntity(ctx, ctx.entity_id_of(tempInflictorEnt));
            }
            tempInflictorEnt = inflictor;
            tempInflictor = qfalse;
            actualMOD = meansOfDeath;
        }

        (*cl).ps.emplacedIndex = 0;

        crate::g_client::G_BreakArm(ctx, ctx.entity_id_of(self_).unwrap(), 0); // unbreak anything we have broken
        (*cl).ps.saberEntityNum = (*cl).saberStoredIndex; // in case we died while our saber was knocked away.

        (*cl).bodyGrabIndex = ENTITYNUM_NONE;
        (*cl).bodyGrabTime = 0;

        if (*cl).holdingObjectiveItem > 0 {
            // carrying a siege objective item - make sure it updates and removes itself from us now
            let objectiveItem =
                &mut ctx.world.g_entities[(*cl).holdingObjectiveItem as usize] as *mut gentity_t;

            if (*objectiveItem).inuse != qfalse {
                if let Some(think_fn) = (*objectiveItem).think.get() {
                    crate::ent_fn_enums::dispatch_think(ctx, think_fn, objectiveItem);
                }
            }
        }

        if ((*cl).inSpaceIndex != 0
            && (*cl).inSpaceIndex != mp_qshared::shared::limits::ENTITYNUM_NONE)
            || ((*cl).ps.eFlags2 & EF2_SHIP_DEATH) != 0
        {
            (*cl).noCorpse = qtrue;
        }

        if (*cl).NPC_class != class_t::CLASS_VEHICLE && (*cl).ps.m_iVehicleNum != 0 {
            // I'm riding a vehicle - tell it I'm getting off
            let veh = &mut ctx.world.g_entities[(*cl).ps.m_iVehicleNum as usize] as *mut gentity_t;
            let vehVeh = (*veh).m_pVehicle;

            if (*veh).inuse != qfalse && !(*veh).client.is_null() && !(*veh).m_pVehicle.is_null() {
                // remember it for obit
                wasInVehicle = (*vehVeh)
                    .m_pVehicleInfo
                    .offset_from(ctx.world.bg_state.g_vehicleInfo.as_ptr())
                    as c_int;
                crate::veh_dispatch::eject(ctx, vehVeh, self_ as *mut bgEntity_t, qtrue);

                if (*(*vehVeh).m_pVehicleInfo).r#type == VH_FIGHTER {
                    // go into "die in ship" mode with flag
                    (*cl).ps.eFlags2 |= EF2_SHIP_DEATH;

                    // put me over where my vehicle exploded
                    crate::g_utils::G_SetOrigin(&mut *(self_), (*((*veh).client)).ps.origin);
                    crate::q_math::_VectorCopy((*((*veh).client)).ps.origin, &mut (*cl).ps.origin);
                }
            }
            // droids throw heads if they haven't yet
            if (*cl).NPC_class == class_t::CLASS_R2D2 {
                if trap::G2API_GetSurfaceRenderStatus(
                    ctx.engine,
                    mp_abi::game::syscalls::G_G2_GETSURFACERENDERSTATUS::GG2GetsurfacerenderstatusArgs::new(
                        (*self_).ghoul2,
                        0,
                        c"head".to_owned(),
                    ),
                ) == 0
                {
                    let mut up: vec3_t = [0.0; 3];
                    AngleVectors((*self_).r.currentAngles, None, None, Some(&mut up));
                    crate::g_utils::G_PlayEffectID(
                        crate::g_utils::G_EffectIndex(cstr("chunks/r2d2head_veh").as_ptr()),
                        (*self_).r.currentOrigin,
                        up,
                    );
                }
            } else if (*cl).NPC_class == class_t::CLASS_R5D2 {
                if trap::G2API_GetSurfaceRenderStatus(
                    ctx.engine,
                    mp_abi::game::syscalls::G_G2_GETSURFACERENDERSTATUS::GG2GetsurfacerenderstatusArgs::new(
                        (*self_).ghoul2,
                        0,
                        c"head".to_owned(),
                    ),
                ) == 0
                {
                    let mut up: vec3_t = [0.0; 3];
                    AngleVectors((*self_).r.currentAngles, None, None, Some(&mut up));
                    crate::g_utils::G_PlayEffectID(
                        crate::g_utils::G_EffectIndex(cstr("chunks/r5d2head_veh").as_ptr()),
                        (*self_).r.currentOrigin,
                        up,
                    );
                }
            }
        }

        if !(*self_).NPC.is_null() {
            let npc = (*self_).NPC;
            if !(*self_).client.is_null()
                && crate::NPC_AI_Jedi::Jedi_WaitingAmbush(&*self_) != qfalse
            {
                // ambushing trooper
                (*cl).noclip = qfalse;
            }
            crate::NPC_combat::NPC_FreeCombatPoint(ctx, (*npc).combatPoint, qfalse);
            if !(*npc).group.is_null() {
                crate::NPC_AI_Utils::AI_GroupMemberKilled(ctx, ctx.entity_id_of(self_));
                crate::NPC_AI_Utils::AI_DeleteSelfFromGroup(ctx, ctx.entity_id_of(self_).unwrap());
            }

            if (*npc).tempGoal.is_some() {
                let tg = (*npc).tempGoal.unwrap();
                crate::g_utils::G_FreeEntity(ctx, Some(tg));
                (*npc).tempGoal = None;
            }
            if false {
                crate::NPC_AI_Jedi::Boba_FlyStop(ctx, ctx.entity_id_of(self_).unwrap());
            }
            if (*self_).s.NPC_class == class_t::CLASS_RANCOR as c_int {
                crate::NPC_AI_Rancor::Rancor_DropVictim(ctx, ctx.entity_id_of(self_).unwrap());
            }
        }
        if !attacker.is_null() && !(*attacker).NPC.is_null() {
            let anpc = (*attacker).NPC;
            if !(*anpc).group.is_null() && (*(*anpc).group).enemy == self_ {
                (*(*anpc).group).enemy = core::ptr::null_mut();
            }
        }

        // Cheap method until/if I decide to put fancier stuff in
        if (*cl).ps.weapon == WP_SABER as c_int
            && (*cl).ps.saberHolstered == 0
            && (*cl).ps.saberEntityNum != 0
        {
            if (*cl).ps.saberInFlight == qfalse && (*cl).saber[0].soundOff != 0 {
                crate::g_utils::G_Sound(
                    ctx,
                    ctx.entity_id_of(self_),
                    CHAN_AUTO,
                    (*cl).saber[0].soundOff,
                );
            }
            if (*cl).saber[1].soundOff != 0 && (*cl).saber[1].model[0] != 0 {
                crate::g_utils::G_Sound(
                    ctx,
                    ctx.entity_id_of(self_),
                    CHAN_AUTO,
                    (*cl).saber[1].soundOff,
                );
            }
        }

        // Use any target we had
        G_UseTargets(ctx, ctx.entity_id_of(self_), ctx.entity_id_of(self_));

        if ctx.world.cvars.g_slowmoDuelEnd.integer != 0
            && (ctx.world.cvars.g_gametype.integer == GT_DUEL
                || ctx.world.cvars.g_gametype.integer == GT_POWERDUEL)
            && !attacker.is_null()
            && (*attacker).inuse != qfalse
            && !(*attacker).client.is_null()
        {
            if ctx.world.globals.gDoSlowMoDuel == qfalse {
                ctx.world.globals.gDoSlowMoDuel = qtrue;
                ctx.world.globals.gSlowMoDuelTime = ctx.world.level.time;
            }
        }

        // Make sure the jetpack is turned off.
        crate::g_items::Jetpack_Off(&mut *self_);

        (*cl).ps.heldByClient = 0;
        (*cl).beingThrown = 0;
        (*cl).doingThrow = 0;
        mp_bg::bg_pmove::BG_ClearRocketLock(&mut (*cl).ps as *mut playerState_t);
        (*cl).isHacking = 0;
        (*cl).ps.hackingTime = 0;

        if !inflictor.is_null()
            && (*inflictor).activator.is_some()
            && (*inflictor).client.is_null()
            && (*attacker).client.is_null()
            && (*inflictor).s.weapon == WP_TURRET as c_int
        {
            let act = &mut ctx.world.g_entities[(*inflictor).activator.unwrap().0 as usize]
                as *mut gentity_t;
            if !(*act).client.is_null() && (*act).inuse != qfalse {
                attacker = act;
            }
        }

        if !(*self_).client.is_null() && (*cl).ps.isJediMaster != qfalse {
            wasJediMaster = qtrue;
        }

        // if he was charging or anything else, kill the sound
        crate::g_utils::G_MuteSound(ctx, (*self_).s.number, CHAN_WEAPON);

        crate::g_weapon::BlowDetpacks(ctx, ctx.entity_id_of(self_).unwrap()); // blow detpacks if they're planted

        (*cl).ps.fd.forceDeactivateAll = 1;

        if (self_ == attacker || (*attacker).client.is_null())
            && (meansOfDeath == meansOfDeath_t::MOD_CRUSH as c_int
                || meansOfDeath == meansOfDeath_t::MOD_FALLING as c_int
                || meansOfDeath == meansOfDeath_t::MOD_TRIGGER_HURT as c_int
                || meansOfDeath == meansOfDeath_t::MOD_UNKNOWN as c_int
                || meansOfDeath == meansOfDeath_t::MOD_SUICIDE as c_int)
            && (*cl).ps.otherKillerTime > ctx.world.level.time
        {
            // remember who last attacked us
            attacker = &mut ctx.world.g_entities[(*cl).ps.otherKiller as usize] as *mut gentity_t;
            if (*cl).otherKillerMOD != meansOfDeath_t::MOD_UNKNOWN as c_int {
                actualMOD = (*cl).otherKillerMOD;
            }
            if (*cl).otherKillerVehWeapon > 0 {
                tempInflictorEnt = crate::g_utils::G_Spawn(ctx);
                if !tempInflictorEnt.is_null() {
                    tempInflictor = qtrue;
                    (*tempInflictorEnt).classname = c"vehicle_proj".as_ptr() as *mut c_char;
                    (*tempInflictorEnt).s.otherEntityNum2 = (*cl).otherKillerVehWeapon - 1;
                    (*tempInflictorEnt).s.weapon = (*cl).otherKillerWeaponType;
                }
            }
        }

        // check for an almost capture
        CheckAlmostCapture(&*self_, attacker.as_ref());

        (*cl).ps.pm_type = pmtype_t::PM_DEAD as c_int;
        (*cl).ps.pm_flags &= !PMF_STUCK_TO_WALL;

        let mut killer: c_int;
        let mut killer_name: String;
        if !attacker.is_null() {
            killer = (*attacker).s.number;
            if !(*attacker).client.is_null() {
                killer_name = cstr_to_str((*((*attacker).client)).pers.netname.as_ptr());
            } else {
                killer_name = "<non-client>".to_string();
            }
        } else {
            killer = ENTITYNUM_WORLD;
            killer_name = "<world>".to_string();
        }

        if killer < 0 || killer >= MAX_CLIENTS as c_int {
            killer = ENTITYNUM_WORLD;
            killer_name = "<world>".to_string();
        }

        let obit: String;
        if meansOfDeath < 0 || meansOfDeath as usize >= modNames.len() {
            obit = "<bad obituary>".to_string();
        } else if modNames[meansOfDeath as usize].is_null() {
            // §19: C's `G_LogPrintf("%s", NULL)` for the three trailing NULL
            // modNames slots (42-44) is UB; glibc renders NULL as "(null)".
            obit = "(null)".to_string();
        } else {
            obit = cstr_to_str(modNames[meansOfDeath as usize]);
        }

        let s = format!(
            "Kill: {} {} {}: {} killed {} by {}\n",
            killer,
            (*self_).s.number,
            meansOfDeath,
            killer_name,
            cstr_to_str((*cl).pers.netname.as_ptr()),
            obit
        );
        crate::g_main::G_LogPrintf(ctx, cstr(&s).as_ptr());

        if ctx.world.cvars.g_austrian.integer != 0
            && ctx.world.cvars.g_gametype.integer == GT_DUEL
            && ctx.world.level.numPlayingClients >= 2
        {
            let spawnTime = if (*ctx
                .world
                .level
                .clients
                .add(ctx.world.level.sortedClients[0] as usize))
            .respawnTime
                > (*ctx
                    .world
                    .level
                    .clients
                    .add(ctx.world.level.sortedClients[1] as usize))
                .respawnTime
            {
                (*ctx
                    .world
                    .level
                    .clients
                    .add(ctx.world.level.sortedClients[0] as usize))
                .respawnTime
            } else {
                (*ctx
                    .world
                    .level
                    .clients
                    .add(ctx.world.level.sortedClients[1] as usize))
                .respawnTime
            };
            crate::g_main::G_LogPrintf(ctx, cstr("Duel Kill Details:\n").as_ptr());
            let s = format!("Kill Time: {}\n", ctx.world.level.time - spawnTime);
            crate::g_main::G_LogPrintf(ctx, cstr(&s).as_ptr());
            let s = format!(
                "victim: {}, hits on enemy {}\n",
                cstr_to_str((*cl).pers.netname.as_ptr()),
                (*cl).ps.persistant[persEnum_t::PERS_HITS as usize]
            );
            crate::g_main::G_LogPrintf(ctx, cstr(&s).as_ptr());
            if !attacker.is_null() && !(*attacker).client.is_null() {
                let acl = (*attacker).client;
                let s = format!(
                    "killer: {}, hits on enemy {}, health: {}\n",
                    cstr_to_str((*acl).pers.netname.as_ptr()),
                    (*acl).ps.persistant[persEnum_t::PERS_HITS as usize],
                    (*attacker).health
                );
                crate::g_main::G_LogPrintf(ctx, cstr(&s).as_ptr());
                // also - if MOD_SABER, list the animation and saber style
                if meansOfDeath == meansOfDeath_t::MOD_SABER as c_int {
                    let s = format!(
                        "killer saber style: {}, killer saber anim {}\n",
                        (*acl).ps.fd.saberAnimLevel,
                        cstr_to_str(animTable[(*acl).ps.torsoAnim as usize].name)
                    );
                    crate::g_main::G_LogPrintf(ctx, cstr(&s).as_ptr());
                }
            }
        }

        crate::g_log::G_LogWeaponKill(ctx, killer, meansOfDeath);
        crate::g_log::G_LogWeaponDeath(ctx, (*self_).s.number, (*self_).s.weapon);
        if !attacker.is_null() && !(*attacker).client.is_null() && (*attacker).inuse != qfalse {
            crate::g_log::G_LogWeaponFrag(ctx, killer, (*self_).s.number);
        }

        G_BroadcastObit(
            ctx,
            ctx.entity_id_of(self_).unwrap(),
            ctx.entity_id_of(inflictor),
            ctx.entity_id_of(attacker),
            killer,
            actualMOD,
            wasInVehicle,
            wasJediMaster,
        );
        if tempInflictor != qfalse {
            crate::g_utils::G_FreeEntity(ctx, ctx.entity_id_of(tempInflictorEnt));
        }

        (*self_).enemy = Some(ent_id(base, attacker));

        (*cl).ps.persistant[persEnum_t::PERS_KILLED as usize] += 1;

        if self_ == attacker {
            (*cl).ps.fd.suicides += 1;
        }

        if !attacker.is_null() && !(*attacker).client.is_null() {
            // killed by a client of some kind (player, NPC or vehicle)
            let acl = (*attacker).client;
            if (*self_).s.number < MAX_CLIENTS as c_int {
                // only remember real clients
                (*acl).lastkilled_client = (*self_).s.number;
            }

            G_CheckVictoryScript(ctx, ctx.entity_id_of(attacker).unwrap());

            if (*self_).s.number >= MAX_CLIENTS as c_int
                && !(*self_).client.is_null()
                && (*cl).NPC_class != class_t::CLASS_VEHICLE
                && (*self_).s.m_iVehicleNum != 0
            {
                // no credit for droid
            } else if meansOfDeath == meansOfDeath_t::MOD_COLLISION as c_int
                || meansOfDeath == meansOfDeath_t::MOD_VEH_EXPLOSION as c_int
            {
                // no credit for veh-veh collisions?
            } else if attacker == self_
                || crate::g_team::OnSameTeam(
                    ctx,
                    ctx.entity_id_of(self_),
                    ctx.entity_id_of(attacker),
                ) != qfalse
            {
                // killed self or teammate
                if meansOfDeath == meansOfDeath_t::MOD_FALLING as c_int
                    && attacker != self_
                    && (*attacker).s.number < MAX_CLIENTS as c_int
                    && (*attacker).s.m_iVehicleNum != 0
                {
                    // crushed by a teammate in a vehicle, no penalty
                } else if ctx.world.cvars.g_gametype.integer == GT_DUEL {
                    // in duel, if you kill yourself, the person you are dueling against gets a kill for it
                    let mut otherClNum: c_int = -1;
                    if ctx.world.level.sortedClients[0] == (*self_).s.number {
                        otherClNum = ctx.world.level.sortedClients[1];
                    } else if ctx.world.level.sortedClients[1] == (*self_).s.number {
                        otherClNum = ctx.world.level.sortedClients[0];
                    }

                    if otherClNum >= 0
                        && otherClNum < MAX_CLIENTS as c_int
                        && ctx.world.g_entities[otherClNum as usize].inuse != qfalse
                        && !ctx.world.g_entities[otherClNum as usize].client.is_null()
                        && otherClNum != (*attacker).s.number
                    {
                        AddScore(
                            ctx,
                            EntityId::from_num(otherClNum).unwrap(),
                            (*self_).r.currentOrigin,
                            1,
                        );
                    } else {
                        AddScore(
                            ctx,
                            ctx.entity_id_of(attacker).unwrap(),
                            (*self_).r.currentOrigin,
                            -1,
                        );
                    }
                } else {
                    AddScore(
                        ctx,
                        ctx.entity_id_of(attacker).unwrap(),
                        (*self_).r.currentOrigin,
                        -1,
                    );
                    if attacker != self_
                        && (*attacker).s.number < MAX_CLIENTS as c_int
                        && (*self_).s.number < MAX_CLIENTS as c_int
                    {
                        crate::g_cmds::G_CheckTKAutoKickBan(
                            ctx,
                            ctx.entity_id_of(attacker).unwrap(),
                        );
                    }
                }
                if ctx.world.cvars.g_gametype.integer == GT_JEDIMASTER {
                    if !(*self_).client.is_null() && (*cl).ps.isJediMaster != qfalse {
                        // killed ourself so return the saber to the original position
                        crate::g_client::ThrowSaberToAttacker(
                            ctx,
                            ctx.entity_id_of(self_).unwrap(),
                            None,
                        );
                        (*cl).ps.isJediMaster = qfalse;
                    }
                }
            } else {
                if ctx.world.cvars.g_gametype.integer == GT_JEDIMASTER {
                    if (!(*attacker).client.is_null() && (*acl).ps.isJediMaster != qfalse)
                        || (!(*self_).client.is_null() && (*cl).ps.isJediMaster != qfalse)
                    {
                        AddScore(
                            ctx,
                            ctx.entity_id_of(attacker).unwrap(),
                            (*self_).r.currentOrigin,
                            1,
                        );

                        if !(*self_).client.is_null() && (*cl).ps.isJediMaster != qfalse {
                            crate::g_client::ThrowSaberToAttacker(
                                ctx,
                                ctx.entity_id_of(self_).unwrap(),
                                ctx.entity_id_of(attacker),
                            );
                            (*cl).ps.isJediMaster = qfalse;
                        }
                    } else {
                        let jmEnt = G_GetJediMaster(ctx);

                        if !jmEnt.is_null() && !(*jmEnt).client.is_null() {
                            AddScore(
                                ctx,
                                ctx.entity_id_of(jmEnt).unwrap(),
                                (*self_).r.currentOrigin,
                                1,
                            );
                        }
                    }
                } else {
                    AddScore(
                        ctx,
                        ctx.entity_id_of(attacker).unwrap(),
                        (*self_).r.currentOrigin,
                        1,
                    );
                }

                if meansOfDeath == meansOfDeath_t::MOD_STUN_BATON as c_int {
                    // play humiliation on player
                    (*acl).ps.persistant[persEnum_t::PERS_GAUNTLET_FRAG_COUNT as usize] += 1;

                    (*acl).rewardTime = ctx.world.level.time + REWARD_SPRITE_TIME;

                    // also play humiliation on target
                    (*cl).ps.persistant[persEnum_t::PERS_PLAYEREVENTS as usize] ^=
                        PLAYEREVENT_GAUNTLETREWARD;
                }

                // check for two kills in a short amount of time
                if ctx.world.level.time - (*acl).lastKillTime < CARNAGE_REWARD_TIME {
                    // play excellent on player
                    (*acl).ps.persistant[persEnum_t::PERS_EXCELLENT_COUNT as usize] += 1;

                    (*acl).rewardTime = ctx.world.level.time + REWARD_SPRITE_TIME;
                }
                (*acl).lastKillTime = ctx.world.level.time;
            }
        } else if meansOfDeath == meansOfDeath_t::MOD_COLLISION as c_int
            || meansOfDeath == meansOfDeath_t::MOD_VEH_EXPLOSION as c_int
        {
            // no credit for veh-veh collisions?
        } else {
            if !(*self_).client.is_null() && (*cl).ps.isJediMaster != qfalse {
                // killed ourself so return the saber to the original position
                crate::g_client::ThrowSaberToAttacker(ctx, ctx.entity_id_of(self_).unwrap(), None);
                (*cl).ps.isJediMaster = qfalse;
            }

            if ctx.world.cvars.g_gametype.integer == GT_DUEL {
                // in duel, if you kill yourself, the person you are dueling against gets a kill for it
                let mut otherClNum: c_int = -1;
                if ctx.world.level.sortedClients[0] == (*self_).s.number {
                    otherClNum = ctx.world.level.sortedClients[1];
                } else if ctx.world.level.sortedClients[1] == (*self_).s.number {
                    otherClNum = ctx.world.level.sortedClients[0];
                }

                if otherClNum >= 0
                    && otherClNum < MAX_CLIENTS as c_int
                    && ctx.world.g_entities[otherClNum as usize].inuse != qfalse
                    && !ctx.world.g_entities[otherClNum as usize].client.is_null()
                    && otherClNum != (*self_).s.number
                {
                    AddScore(
                        ctx,
                        EntityId::from_num(otherClNum).unwrap(),
                        (*self_).r.currentOrigin,
                        1,
                    );
                } else {
                    AddScore(
                        ctx,
                        ctx.entity_id_of(self_).unwrap(),
                        (*self_).r.currentOrigin,
                        -1,
                    );
                }
            } else {
                AddScore(
                    ctx,
                    ctx.entity_id_of(self_).unwrap(),
                    (*self_).r.currentOrigin,
                    -1,
                );
            }
        }

        // Add team bonuses
        crate::g_team::Team_FragBonuses(
            ctx,
            ctx.entity_id_of(self_).unwrap(),
            ctx.entity_id_of(inflictor),
            ctx.entity_id_of(attacker),
        );

        // if I committed suicide, the flag does not fall, it returns.
        if meansOfDeath == meansOfDeath_t::MOD_SUICIDE as c_int {
            if (*cl).ps.powerups[PW_NEUTRALFLAG as usize] != 0 {
                crate::g_team::Team_ReturnFlag(ctx, TEAM_FREE as c_int);
                (*cl).ps.powerups[PW_NEUTRALFLAG as usize] = 0;
            } else if (*cl).ps.powerups[PW_REDFLAG as usize] != 0 {
                crate::g_team::Team_ReturnFlag(ctx, TEAM_RED as c_int);
                (*cl).ps.powerups[PW_REDFLAG as usize] = 0;
            } else if (*cl).ps.powerups[PW_BLUEFLAG as usize] != 0 {
                crate::g_team::Team_ReturnFlag(ctx, TEAM_BLUE as c_int);
                (*cl).ps.powerups[PW_BLUEFLAG as usize] = 0;
            }
        }

        // if client is in a nodrop area, don't drop anything (but return CTF flags!)
        let contents = trap::PointContents(
            ctx.engine,
            mp_abi::game::syscalls::G_POINTCONTENTS::GPointcontentsArgs::new(
                &(*self_).r.currentOrigin as *const vec3_t,
                -1,
            ),
        );
        if (contents & CONTENTS_NODROP) == 0 && (*cl).ps.fallingToDeath == qfalse {
            if (*self_).s.eType != entityType_t::ET_NPC as c_int {
                TossClientItems(ctx, ctx.entity_id_of(self_).unwrap());
            }
        } else {
            if (*cl).ps.powerups[PW_NEUTRALFLAG as usize] != 0 {
                crate::g_team::Team_ReturnFlag(ctx, TEAM_FREE as c_int);
            } else if (*cl).ps.powerups[PW_REDFLAG as usize] != 0 {
                crate::g_team::Team_ReturnFlag(ctx, TEAM_RED as c_int);
            } else if (*cl).ps.powerups[PW_BLUEFLAG as usize] != 0 {
                crate::g_team::Team_ReturnFlag(ctx, TEAM_BLUE as c_int);
            }
        }

        if meansOfDeath_t::MOD_TEAM_CHANGE as c_int == meansOfDeath {
            // Give them back a point since they didn't really die.
            AddScore(
                ctx,
                ctx.entity_id_of(self_).unwrap(),
                (*self_).r.currentOrigin,
                1,
            );
        } else {
            crate::g_cmds::Cmd_Score_f(ctx, ctx.entity_id_of(self_).unwrap()); // show scores
        }

        // send updated scores to any clients that are following this one
        for i in 0..ctx.world.level.maxclients {
            let client = ctx.world.level.clients.add(i as usize);
            if (*client).pers.connected != CON_CONNECTED {
                continue;
            }
            if (*client).sess.sessionTeam != TEAM_SPECTATOR {
                continue;
            }
            if (*client).sess.spectatorClient == (*self_).s.number {
                crate::g_cmds::Cmd_Score_f(ctx, EntityId(i as u32));
            }
        }

        (*self_).takedamage = qtrue; // can still be gibbed

        (*self_).s.weapon = WP_NONE as c_int;
        (*self_).s.powerups = 0;
        if (*self_).s.eType != entityType_t::ET_NPC as c_int {
            // handled differently for NPCs
            (*self_).r.contents = CONTENTS_CORPSE;
        }
        (*cl).ps.zoomMode = 0; // Turn off zooming when we die

        (*self_).s.loopSound = 0;
        (*self_).s.loopIsSoundset = qfalse;

        if (*self_).s.eType != entityType_t::ET_NPC as c_int {
            // handled differently for NPCs
            (*self_).r.maxs[2] = -8.0;
        }

        // don't allow respawn until the death anim is done
        (*cl).respawnTime = ctx.world.level.time + 1700;

        // remove powerups
        (*cl).ps.powerups.fill(0);

        // NOTENOTE No gib deaths right now, this is star wars.
        {
            // normal death
            // Raven's function-`static int i` rotates EV_DEATH1 0..2 across deaths;
            // world-owned per §B3 (`game_globals.rs`).
            let mut i_val = ctx.world.globals.death_anim_i;

            // Referee probe capture: holdrand before the death-anim draw.
            let probe_rin = ctx.world.bg_state.rng.dbg_holdrand();
            let anim = G_PickDeathAnim(
                ctx,
                ctx.entity_id_of(self_),
                (*self_).pos1,
                damage,
                meansOfDeath,
                HL_NONE,
            );
            // Referee probe: G_PickDeathAnim inputs (pos, dmg, mod) + RNG in/out.
            probe!(
                "DEATH_ANIM",
                "t={} en={} dmg={} mod={} p={:08x},{:08x},{:08x} rin={:08x} rout={:08x} anim={}",
                ctx.world.level.time,
                (*self_).s.number,
                damage,
                meansOfDeath,
                (*self_).pos1[0].to_bits(),
                (*self_).pos1[1].to_bits(),
                (*self_).pos1[2].to_bits(),
                probe_rin,
                ctx.world.bg_state.rng.dbg_holdrand(),
                anim,
            );

            if anim >= 1 {
                // Some droids don't have death anims
                if (*self_).health <= GIB_HEALTH {
                    (*self_).health = GIB_HEALTH + 1;
                }

                (*cl).respawnTime = ctx.world.level.time + 1000;

                sPMType = (*cl).ps.pm_type;
                (*cl).ps.pm_type = pmtype_t::PM_NORMAL as c_int; // don't want pm type interfering with our setanim calls.

                if (*self_).inuse != qfalse {
                    // not disconnecting
                    crate::g_utils::G_SetAnim(
                        ctx,
                        ctx.entity_id_of(self_).unwrap(),
                        core::ptr::null_mut(),
                        SETANIM_BOTH,
                        anim,
                        SETANIM_FLAG_OVERRIDE | SETANIM_FLAG_HOLD | SETANIM_FLAG_RESTART,
                        0,
                    );
                }

                (*cl).ps.pm_type = sPMType;

                if meansOfDeath == meansOfDeath_t::MOD_SABER as c_int
                    || (meansOfDeath == meansOfDeath_t::MOD_MELEE as c_int
                        && G_HeavyMelee(ctx, ctx.entity_id_of(attacker)) != qfalse)
                {
                    // saber or heavy melee (claws)
                    crate::g_client::G_UpdateClientAnims(
                        ctx,
                        ctx.entity_id_of(self_).unwrap(),
                        1.0,
                    );
                    G_CheckForDismemberment(
                        ctx,
                        ctx.entity_id_of(self_).unwrap(),
                        ctx.entity_id_of(attacker),
                        (*self_).pos1,
                        damage,
                        anim,
                        qfalse,
                    );
                }
            } else if !(*self_).NPC.is_null()
                && !(*self_).client.is_null()
                && (*cl).NPC_class != class_t::CLASS_MARK1
                && (*cl).NPC_class != class_t::CLASS_VEHICLE
            {
                // in this case if we're an NPC it's my guess that we want to get removed straight away.
                (*self_).think = Some(EntThink::G_FreeEntity).into();
                (*self_).nextthink = ctx.world.level.time;
            }

            if wasJediMaster != qfalse {
                G_AddEvent(&mut *(self_), entity_event_t::EV_DEATH1 as c_int + i_val, 1);
            } else {
                G_AddEvent(&mut *(self_), entity_event_t::EV_DEATH1 as c_int + i_val, 0);
            }

            if self_ != attacker {
                // don't make NPCs want to murder you on respawn for killing yourself!
                G_DeathAlert(
                    ctx,
                    ctx.entity_id_of(self_).unwrap(),
                    ctx.entity_id_of(attacker),
                );
            }

            // the body can still be gibbed
            if (*self_).NPC.is_null() {
                // don't remove NPCs like this!
                (*self_).die = Some(EntDie::body_die).into();
            }

            // It won't gib, it will disintegrate (because this is Star Wars).
            (*self_).takedamage = qtrue;

            // globally cycle through the different death animations
            i_val = (i_val + 1) % 3;
            ctx.world.globals.death_anim_i = i_val;
        }

        if !(*self_).NPC.is_null() {
            // If an NPC, make sure we start running our scripts again
            (*((*self_).NPC)).nextBStateThink = ctx.world.level.time;
        }

        if G_ActivateBehavior(ctx, ctx.entity_id_of(self_), bSet_t::BSET_DEATH as c_int) != qfalse {
            //deathScript = qtrue;
        }

        if !(*self_).NPC.is_null() && ((*((*self_).NPC)).scriptFlags & SCF_FFDEATH) != 0 {
            if G_ActivateBehavior(ctx, ctx.entity_id_of(self_), bSet_t::BSET_FFDEATH as c_int)
                != qfalse
            {
                //deathScript = qtrue;
            }
            crate::g_utils::G_UseTargets2(
                ctx,
                ctx.entity_id_of(self_),
                ctx.entity_id_of(self_),
                (*self_).target4,
            );
        }

        // Free up any timers we may have on us.
        crate::g_timer::TIMER_Clear2(ctx, ctx.entity_id_of(self_));

        trap::LinkEntity(
            ctx.engine,
            mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(self_.cast()),
        );

        if !(*self_).NPC.is_null() {
            (*((*self_).NPC)).timeOfDeath = ctx.world.level.time;
        }

        // Start any necessary death fx for this entity
        DeathFX(ctx, ctx.entity_id_of(self_));

        if ctx.world.cvars.g_gametype.integer == GT_POWERDUEL
            && ctx.world.globals.g_noPDuelCheck == 0
        {
            // powerduel checks
            if (*cl).sess.duelTeam == DUELTEAM_LONE as c_int {
                // automatically means a win as there is only one
                G_AddPowerDuelScore(ctx, DUELTEAM_DOUBLE as c_int, 1);
                G_AddPowerDuelLoserScore(ctx, DUELTEAM_LONE as c_int, 1);
                ctx.world.globals.g_endPDuel = qtrue;
            } else if (*cl).sess.duelTeam == DUELTEAM_DOUBLE as c_int {
                let mut i = 0;
                let mut heLives: qboolean = qfalse;

                while i < MAX_CLIENTS as c_int {
                    let check = &mut ctx.world.g_entities[i as usize] as *mut gentity_t;
                    let checkClient = (*check).client;
                    if (*check).inuse != qfalse
                        && !checkClient.is_null()
                        && (*check).s.number != (*self_).s.number
                        && (*checkClient).pers.connected == CON_CONNECTED
                        && (*checkClient).iAmALoser == qfalse
                        && (*checkClient).ps.stats[statIndex_t::STAT_HEALTH as usize] > 0
                        && (*checkClient).sess.sessionTeam != TEAM_SPECTATOR
                        && (*checkClient).sess.duelTeam == DUELTEAM_DOUBLE as c_int
                    {
                        // still an active living paired duelist so it's not over yet.
                        heLives = qtrue;
                        break;
                    }
                    i += 1;
                }

                if heLives == qfalse {
                    // they're all dead, give the lone duelist the win.
                    G_AddPowerDuelScore(ctx, DUELTEAM_LONE as c_int, 1);
                    G_AddPowerDuelLoserScore(ctx, DUELTEAM_DOUBLE as c_int, 1);
                    ctx.world.globals.g_endPDuel = qtrue;
                }
            }
        }
    }
}

/// Raven `CheckArmor`.
///
/// Source: `oracle/codemp/game/g_combat.c:3019-3071`
pub fn CheckArmor(ctx: &mut GameContext, ent: EntityId, damage: c_int, dflags: c_int) -> c_int {
    if damage == 0 {
        return 0;
    }

    // ent may be an NPC/vehicle — `.client` is a pool client, deref stays raw (2b).
    let client = ctx.entity(ent).client;

    if client.is_null() {
        return 0;
    }

    if (dflags & DAMAGE_NO_ARMOR) != 0 {
        return 0;
    }

    if unsafe { (*client).NPC_class } == class_t::CLASS_VEHICLE
        && !ctx.entity(ent).m_pVehicle.is_null()
        && unsafe { (*client).ps.electrifyTime } > ctx.world.level.time
    {
        // ion-cannon has disabled this ship's shields, take damage on hull!
        return 0;
    }
    // armor
    let count = unsafe { (*client).ps.stats[statIndex_t::STAT_ARMOR as usize] };

    let mut save;
    if (dflags & DAMAGE_HALF_ABSORB) != 0 {
        // Half the damage gets absorbed by the shields, rather than 100%
        save = (damage as f32 * ARMOR_PROTECTION).ceil() as c_int;
    } else {
        // All the damage gets absorbed by the shields.
        save = damage;
    }

    // save is the most damage that the armor is eligible to protect, but it's limited by the total armor.
    if save >= count {
        save = count;
    }

    if save == 0 {
        return 0;
    }

    unsafe {
        if (dflags & DAMAGE_HALF_ARMOR_REDUCTION) != 0 {
            // Armor isn't whittled so easily by sniper shots.
            (*client).ps.stats[statIndex_t::STAT_ARMOR as usize] -=
                (save as f32 * ARMOR_REDUCTION_FACTOR) as c_int;
        } else {
            (*client).ps.stats[statIndex_t::STAT_ARMOR as usize] -= save;
        }
    }

    save
}

/// Raven `G_ApplyKnockback`.
///
/// `newDir` is read-only (`VectorScale` reads it into `kvel`), so it stays
/// by-value.
/// Source: `oracle/codemp/game/g_combat.c:3074-3121`
pub fn G_ApplyKnockback(ctx: &mut GameContext, targ: EntityId, newDir: vec3_t, knockback: f32) {
    let mut kvel: vec3_t = [0.0; 3];

    let mass: f32 = if ctx.entity(targ).physicsBounce > 0.0 {
        ctx.entity(targ).physicsBounce // override the mass
    } else {
        200.0
    };

    let g_knockback = ctx.world.cvars.g_knockback.value;
    if ctx.world.cvars.g_gravity.value > 0.0 {
        _VectorScale(
            newDir,
            ((g_knockback * knockback / mass) as f64 * 0.8) as f32,
            &mut kvel,
        );
        kvel[2] = ((newDir[2] * g_knockback * knockback / mass) as f64 * 1.5) as f32;
    } else {
        _VectorScale(newDir, g_knockback * knockback / mass, &mut kvel);
    }

    // targ may be an NPC — `.client` is a pool client, deref stays raw (2b).
    let client = ctx.entity(targ).client;
    if !client.is_null() {
        unsafe {
            _VectorAdd((*client).ps.velocity, kvel, &mut (*client).ps.velocity);
        }
    } else if ctx.entity(targ).s.pos.trType != trType_t::TR_STATIONARY
        && ctx.entity(targ).s.pos.trType != trType_t::TR_LINEAR_STOP
        && ctx.entity(targ).s.pos.trType != trType_t::TR_NONLINEAR_STOP
    {
        let level_time = ctx.world.level.time;
        let e = ctx.entity_mut(targ);
        let trDelta = e.s.pos.trDelta;
        _VectorAdd(trDelta, kvel, &mut e.s.pos.trDelta);
        e.s.pos.trBase = e.r.currentOrigin;
        e.s.pos.trTime = level_time;
    }

    // set the timer so that the other client can't cancel out the movement immediately
    if !client.is_null() && unsafe { (*client).ps.pm_time } == 0 {
        let mut t = (knockback * 2.0) as c_int;
        if t < 50 {
            t = 50;
        }
        if t > 200 {
            t = 200;
        }
        unsafe {
            (*client).ps.pm_time = t;
            (*client).ps.pm_flags |= PMF_TIME_KNOCKBACK;
        }
    }
}

/// Raven `RaySphereIntersections`.
///
/// `dir` is normalized in place (mutate-through → `&mut`); `origin` and
/// `point` are read-only. C: `vec3_t intersections[2]` → `*mut vec3_t` to the
/// first of the two slots.
/// Source: `oracle/codemp/game/g_combat.c:3128-3158`
pub fn RaySphereIntersections(
    origin: vec3_t,
    radius: f32,
    point: vec3_t,
    dir: &mut vec3_t,
    intersections: *mut vec3_t,
) -> c_int {
    unsafe {
        // normalize dir so a = 1
        VectorNormalize(dir);
        let b = 2.0
            * (dir[0] * (point[0] - origin[0])
                + dir[1] * (point[1] - origin[1])
                + dir[2] * (point[2] - origin[2]));
        let c = (point[0] - origin[0]) * (point[0] - origin[0])
            + (point[1] - origin[1]) * (point[1] - origin[1])
            + (point[2] - origin[2]) * (point[2] - origin[2])
            - radius * radius;

        let d = b * b - 4.0 * c;
        // VectorMA(point, t, dir, out): out[i] = point[i] + t * dir[i]
        let ma = |t: f32| {
            [
                point[0] + t * dir[0],
                point[1] + t * dir[1],
                point[2] + t * dir[2],
            ]
        };
        if d > 0.0 {
            // Raven: `t = (- b + sqrt(d)) / 2`. `sqrt` is libm's `double sqrt`,
            // so `d` promotes to double and the whole root is evaluated in f64
            // before narrowing to the f32 `t` — evaluating in f32 here diverges
            // by a last bit on irrational `sqrt(d)`.
            let t = ((-(b as f64) + (d as f64).sqrt()) / 2.0) as f32;
            *intersections.add(0) = ma(t);
            let t = ((-(b as f64) - (d as f64).sqrt()) / 2.0) as f32;
            *intersections.add(1) = ma(t);
            2
        } else if d == 0.0 {
            // Raven: `t = (- b) / 2` — no `sqrt`, so this stays f32 (`2` is an
            // int divisor, promoting only to float).
            let t = -b / 2.0;
            *intersections.add(0) = ma(t);
            1
        } else {
            0
        }
    }
}

/// Raven `G_GetDismemberLoc` — get the general area without server-side ghoul2.
///
/// `boltPoint` is written (mutate-through → `&mut`).
/// Source: `oracle/codemp/game/g_combat.c:3192-3262`
pub fn G_GetDismemberLoc(self_: &gentity_t, boltPoint: &mut vec3_t, limbType: c_int) {
    use g2ModelParts_t::*;
    {
        let mut fwd: vec3_t = [0.0; 3];
        let mut right: vec3_t = [0.0; 3];
        let mut up: vec3_t = [0.0; 3];

        AngleVectors(
            self_.r.currentAngles,
            Some(&mut fwd),
            Some(&mut right),
            Some(&mut up),
        );

        *boltPoint = self_.r.currentOrigin;

        let m = limbType;
        if m == G2_MODELPART_HEAD as c_int {
            for i in 0..3 {
                boltPoint[i] += up[i] * 24.0;
            }
        } else if m == G2_MODELPART_WAIST as c_int {
            for i in 0..3 {
                boltPoint[i] += up[i] * 4.0;
            }
        } else if m == G2_MODELPART_LARM as c_int {
            for i in 0..3 {
                boltPoint[i] += up[i] * 18.0;
                boltPoint[i] -= right[i] * 10.0;
            }
        } else if m == G2_MODELPART_RARM as c_int {
            for i in 0..3 {
                boltPoint[i] += up[i] * 18.0;
                boltPoint[i] += right[i] * 10.0;
            }
        } else if m == G2_MODELPART_RHAND as c_int {
            for i in 0..3 {
                boltPoint[i] += up[i] * 8.0;
                boltPoint[i] += right[i] * 10.0;
            }
        } else if m == G2_MODELPART_LLEG as c_int {
            for i in 0..3 {
                boltPoint[i] -= up[i] * 4.0;
                boltPoint[i] -= right[i] * 10.0;
            }
        } else if m == G2_MODELPART_RLEG as c_int {
            for i in 0..3 {
                boltPoint[i] -= up[i] * 4.0;
                boltPoint[i] += right[i] * 10.0;
            }
        }
    }
}

/// Raven `G_GetDismemberBolt`.
///
/// Source: `oracle/codemp/game/g_combat.c:3264-3385`
pub fn G_GetDismemberBolt(
    ctx: &mut GameContext,
    self_: EntityId,
    boltPoint: &mut vec3_t,
    limbType: c_int,
) {
    use g2ModelParts_t::*;
    let mut useBolt = ctx.entity(self_).genericValue5;
    let mut properOrigin: vec3_t = [0.0; 3];
    let mut properAngles: vec3_t = [0.0; 3];
    let mut addVel: vec3_t = [0.0; 3];
    let mut boltMatrix: mdxaBone_t = unsafe { core::mem::zeroed() };
    let mut fVSpeed: f32 = 0.0;
    // self_ may be an NPC — `.client` is a pool client, deref stays raw (2b).
    let client = ctx.entity(self_).client;

    let rotateBone: *const c_char = if limbType == G2_MODELPART_HEAD as c_int {
        c"cranium".as_ptr()
    } else if limbType == G2_MODELPART_WAIST as c_int {
        if ctx.entity(self_).localAnimIndex <= 1 {
            c"thoracic".as_ptr() // humanoid
        } else {
            c"pelvis".as_ptr()
        }
    } else if limbType == G2_MODELPART_LARM as c_int {
        c"lradius".as_ptr()
    } else if limbType == G2_MODELPART_RARM as c_int {
        c"rradius".as_ptr()
    } else if limbType == G2_MODELPART_RHAND as c_int {
        c"rhand".as_ptr()
    } else if limbType == G2_MODELPART_LLEG as c_int {
        c"ltibia".as_ptr()
    } else if limbType == G2_MODELPART_RLEG as c_int {
        c"rtibia".as_ptr()
    } else {
        c"rtibia".as_ptr()
    };

    let ghoul2 = ctx.entity(self_).ghoul2;
    useBolt = trap::G2API_AddBolt(
        ctx.engine,
        mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs::new(ghoul2, 0, unsafe {
            core::ffi::CStr::from_ptr(rotateBone).to_owned()
        }),
    );

    unsafe {
        crate::q_math::_VectorCopy((*client).ps.origin, &mut properOrigin);
        crate::q_math::_VectorCopy((*client).ps.viewangles, &mut properAngles);

        // try to predict the origin based on velocity so it's more like what the client is seeing
        crate::q_math::_VectorCopy((*client).ps.velocity, &mut addVel);
        crate::q_math::VectorNormalize(&mut addVel);

        if (*client).ps.velocity[0] < 0.0 {
            fVSpeed += -(*client).ps.velocity[0];
        } else {
            fVSpeed += (*client).ps.velocity[0];
        }
        if (*client).ps.velocity[1] < 0.0 {
            fVSpeed += -(*client).ps.velocity[1];
        } else {
            fVSpeed += (*client).ps.velocity[1];
        }
        if (*client).ps.velocity[2] < 0.0 {
            fVSpeed += -(*client).ps.velocity[2];
        } else {
            fVSpeed += (*client).ps.velocity[2];
        }
    }

    fVSpeed = (fVSpeed as f64 * 0.08) as f32;

    properOrigin[0] += addVel[0] * fVSpeed;
    properOrigin[1] += addVel[1] * fVSpeed;
    properOrigin[2] += addVel[2] * fVSpeed;

    properAngles[0] = 0.0;
    properAngles[1] = unsafe { (*client).ps.viewangles[YAW] };
    properAngles[2] = 0.0;

    let level_time = ctx.world.level.time;
    let modelScale = ctx.entity(self_).modelScale;

    trap::G2API_GetBoltMatrix(
        ctx.engine,
        mp_abi::game::syscalls::G_G2_GETBOLT::GG2GetboltArgs::new(
            ghoul2,
            0,
            useBolt,
            &mut boltMatrix as *mut mdxaBone_t,
            &properAngles as *const vec3_t,
            &properOrigin as *const vec3_t,
            level_time,
            core::ptr::null_mut(),
            &modelScale as *const vec3_t,
        ),
    );

    boltPoint[0] = boltMatrix.matrix[0][3];
    boltPoint[1] = boltMatrix.matrix[1][3];
    boltPoint[2] = boltMatrix.matrix[2][3];

    trap::G2API_GetBoltMatrix(
        ctx.engine,
        mp_abi::game::syscalls::G_G2_GETBOLT::GG2GetboltArgs::new(
            ghoul2,
            1,
            0,
            &mut boltMatrix as *mut mdxaBone_t,
            &properAngles as *const vec3_t,
            &properOrigin as *const vec3_t,
            level_time,
            core::ptr::null_mut(),
            &modelScale as *const vec3_t,
        ),
    );

    if !client.is_null() && limbType == G2_MODELPART_RHAND as c_int {
        // Make some saber hit sparks over the severed wrist area
        let mut boltAngles: vec3_t = [0.0; 3];

        boltAngles[0] = -boltMatrix.matrix[0][1];
        boltAngles[1] = -boltMatrix.matrix[1][1];
        boltAngles[2] = -boltMatrix.matrix[2][1];

        let te = G_TempEntity(ctx, *boltPoint, entity_event_t::EV_SABER_HIT as c_int);
        let te = ctx.entity_id_of(te).unwrap();
        let self_number = ctx.entity(self_).s.number;
        ctx.entity_mut(te).s.otherEntityNum = self_number;
        ctx.entity_mut(te).s.otherEntityNum2 = ENTITYNUM_NONE;
        ctx.entity_mut(te).s.weapon = 0; // saberNum
        ctx.entity_mut(te).s.legsAnim = 0; // bladeNum

        let bp = *boltPoint;
        crate::q_math::_VectorCopy(bp, &mut ctx.entity_mut(te).s.origin);
        crate::q_math::_VectorCopy(boltAngles, &mut ctx.entity_mut(te).s.angles);

        if ctx.entity(te).s.angles[0] == 0.0
            && ctx.entity(te).s.angles[1] == 0.0
            && ctx.entity(te).s.angles[2] == 0.0
        {
            // don't let it play with no direction
            ctx.entity_mut(te).s.angles[1] = 1.0;
        }

        ctx.entity_mut(te).s.eventParm = 16; // lots of sparks
    }
}

