/// Raven `LimbThink`.
///
/// Source: `oracle/codemp/game/g_combat.c:3391-3430`
pub fn LimbThink(ctx: &mut GameContext, ent: EntityId) {
    use g2ModelParts_t::*;
    let gravity: f32 = 3.0;
    let mut mass: f32 = 0.09;
    let mut bounce: f32 = 1.3;

    if ctx.entity(ent).s.modelGhoul2 == G2_MODELPART_HEAD as c_int {
        mass = 0.08;
        bounce = 1.4;
    } else if ctx.entity(ent).s.modelGhoul2 == G2_MODELPART_WAIST as c_int {
        mass = 0.1;
        bounce = 1.2;
    }
    // G2_MODELPART_LARM/RARM/RHAND/LLEG/RLEG/default: leave defaults

    if ctx.entity(ent).speed < ctx.world.level.time as f32 {
        ctx.entity_mut(ent).think = Some(EntThink::G_FreeEntity).into();
        let time = ctx.world.level.time;
        ctx.entity_mut(ent).nextthink = time;
        return;
    }

    if ctx.entity(ent).genericValue5 <= ctx.world.level.time {
        // this will be every frame by standard, but we want to compensate in case sv_fps is not 20.
        crate::g_exphysics::G_RunExPhys(
            ctx,
            ent,
            gravity,
            mass,
            bounce,
            qtrue,
            core::ptr::null_mut(),
            0,
        );
        let time = ctx.world.level.time + 50;
        ctx.entity_mut(ent).genericValue5 = time;
    }

    let time = ctx.world.level.time;
    ctx.entity_mut(ent).nextthink = time;
}

/// Raven `G_Dismember`.
///
/// Source: `oracle/codemp/game/g_combat.c:3436-3620`
pub fn G_Dismember(
    ctx: &mut GameContext,
    ent: EntityId,
    enemy: Option<EntityId>,
    point: vec3_t,
    limbType: c_int,
    limbRollBase: f32,
    limbPitchBase: f32,
    deathAnim: c_int,
    postDeath: qboolean,
) {
    use animNumber_t::*;
    use g2ModelParts_t::*;
    // ent/enemy `.client` are pool clients (deref raw, trap 2b); the body keeps
    // one unsafe scope for those. Entity/limb fields route through the accessor.
    let ghoul2 = ctx.entity(ent).ghoul2;
    unsafe {
        let mut newPoint: vec3_t = [0.0; 3];
        let mut dir: vec3_t = [0.0; 3];
        let mut vel: vec3_t = [0.0; 3];
        let mut limbName: [c_char; MAX_QPATH as usize] = [0; MAX_QPATH as usize];
        let mut stubName: [c_char; MAX_QPATH as usize] = [0; MAX_QPATH as usize];
        let mut stubCapName: [c_char; MAX_QPATH as usize] = [0; MAX_QPATH as usize];

        if limbType == G2_MODELPART_HEAD as c_int {
            write_cstr_field(&mut limbName, "head");
            write_cstr_field(&mut stubCapName, "torso_cap_head");
        } else if limbType == G2_MODELPART_WAIST as c_int {
            write_cstr_field(&mut limbName, "torso");
            write_cstr_field(&mut stubCapName, "hips_cap_torso");
        } else if limbType == G2_MODELPART_LARM as c_int {
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"l_arm".as_ptr(),
                limbName.as_mut_ptr(),
                limbName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"torso".as_ptr(),
                stubName.as_mut_ptr(),
                stubName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            write_cstr_field(
                &mut stubCapName,
                &format!("{}_cap_l_arm", cstr_to_str(stubName.as_ptr())),
            );
        } else if limbType == G2_MODELPART_RARM as c_int {
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"r_arm".as_ptr(),
                limbName.as_mut_ptr(),
                limbName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"torso".as_ptr(),
                stubName.as_mut_ptr(),
                stubName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            write_cstr_field(
                &mut stubCapName,
                &format!("{}_cap_r_arm", cstr_to_str(stubName.as_ptr())),
            );
        } else if limbType == G2_MODELPART_RHAND as c_int {
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"r_hand".as_ptr(),
                limbName.as_mut_ptr(),
                limbName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"r_arm".as_ptr(),
                stubName.as_mut_ptr(),
                stubName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            write_cstr_field(
                &mut stubCapName,
                &format!("{}_cap_r_hand", cstr_to_str(stubName.as_ptr())),
            );
        } else if limbType == G2_MODELPART_LLEG as c_int {
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"l_leg".as_ptr(),
                limbName.as_mut_ptr(),
                limbName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"hips".as_ptr(),
                stubName.as_mut_ptr(),
                stubName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            write_cstr_field(
                &mut stubCapName,
                &format!("{}_cap_l_leg", cstr_to_str(stubName.as_ptr())),
            );
        } else if limbType == G2_MODELPART_RLEG as c_int {
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"r_leg".as_ptr(),
                limbName.as_mut_ptr(),
                limbName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"hips".as_ptr(),
                stubName.as_mut_ptr(),
                stubName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            write_cstr_field(
                &mut stubCapName,
                &format!("{}_cap_r_leg", cstr_to_str(stubName.as_ptr())),
            );
        } else {
            // umm... just default to the right leg, I guess (same as on client)
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"r_leg".as_ptr(),
                limbName.as_mut_ptr(),
                limbName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            mp_bg::bg_g2_utils::BG_GetRootSurfNameWithVariant(
                ghoul2,
                c"hips".as_ptr(),
                stubName.as_mut_ptr(),
                stubName.len() as c_int,
                &ctx.world.bg_state,
                &GameBgTraps::new(ctx.engine),
            );
            write_cstr_field(
                &mut stubCapName,
                &format!("{}_cap_r_leg", cstr_to_str(stubName.as_ptr())),
            );
        }

        if !ghoul2.is_null()
            && trap::G2API_GetSurfaceRenderStatus(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_GETSURFACERENDERSTATUS::GG2GetsurfacerenderstatusArgs::new(
                    ghoul2,
                    0,
                    core::ffi::CStr::from_ptr(limbName.as_ptr()).to_owned(),
                ),
            ) != 0
        {
            // is it already off? If so there's no reason to be doing it again.
            return;
        }

        crate::q_math::_VectorCopy(point, &mut newPoint);
        let limb = crate::g_utils::G_Spawn(ctx);
        let limb = ctx.entity_id_of(limb).unwrap();
        ctx.entity_mut(limb).classname = c"playerlimb".as_ptr() as *mut c_char;

        crate::g_utils::G_SetOrigin(ctx.entity_mut(limb), newPoint);
        crate::q_math::_VectorCopy(newPoint, &mut ctx.entity_mut(limb).s.pos.trBase);
        ctx.entity_mut(limb).think = Some(EntThink::LimbThink).into();
        ctx.entity_mut(limb).touch = Some(EntTouch::LimbTouch).into();
        let speed = (ctx.world.level.time + ctx.world.bg_state.rng.Q_irand(8000, 16000)) as f32;
        ctx.entity_mut(limb).speed = speed;
        let nextthink = ctx.world.level.time + FRAMETIME;
        ctx.entity_mut(limb).nextthink = nextthink;

        ctx.entity_mut(limb).r.svFlags = SVF_USE_CURRENT_ORIGIN;
        ctx.entity_mut(limb).clipmask = MASK_SOLID;
        ctx.entity_mut(limb).r.contents = CONTENTS_TRIGGER;
        ctx.entity_mut(limb).physicsObject = qtrue;
        ctx.entity_mut(limb).r.mins = [-6.0, -6.0, -3.0];
        ctx.entity_mut(limb).r.maxs = [6.0, 6.0, 6.0];

        ctx.entity_mut(limb).s.g2radius = 200;

        ctx.entity_mut(limb).s.eType = entityType_t::ET_GENERAL as c_int;
        ctx.entity_mut(limb).s.weapon = G2_MODEL_PART;
        ctx.entity_mut(limb).s.modelGhoul2 = limbType;
        let ent_number = ctx.entity(ent).s.number;
        ctx.entity_mut(limb).s.modelindex = ent_number;
        // ent may be an NPC — `.client` is a pool client, deref stays raw (2b).
        let ent_client = ctx.entity(ent).client;
        if ent_client.is_null() {
            ctx.entity_mut(limb).s.modelindex = -1;
            ctx.entity_mut(limb).s.otherEntityNum2 = ent_number;
        }

        ctx.entity_mut(limb).s.apos.trDelta = [0.0; 3];

        if !ent_client.is_null() {
            let viewangles = unsafe { (*ent_client).ps.viewangles };
            crate::q_math::_VectorCopy(viewangles, &mut ctx.entity_mut(limb).r.currentAngles);
            crate::q_math::_VectorCopy(viewangles, &mut ctx.entity_mut(limb).s.apos.trBase);
        } else {
            let currentAngles = ctx.entity(ent).r.currentAngles;
            crate::q_math::_VectorCopy(currentAngles, &mut ctx.entity_mut(limb).r.currentAngles);
            crate::q_math::_VectorCopy(currentAngles, &mut ctx.entity_mut(limb).s.apos.trBase);
        }

        // Set up the ExPhys values for the entity.
        ctx.entity_mut(limb).epGravFactor = 0.0;
        ctx.entity_mut(limb).epVelocity = [0.0; 3];
        let currentOrigin = ctx.entity(ent).r.currentOrigin;
        crate::q_math::_VectorSubtract(point, currentOrigin, &mut dir);
        crate::q_math::VectorNormalize(&mut dir);
        if !ent_client.is_null() {
            let velocity = unsafe { (*ent_client).ps.velocity };
            crate::q_math::_VectorCopy(velocity, &mut vel);
        } else {
            let trDelta = ctx.entity(ent).s.pos.trDelta;
            crate::q_math::_VectorCopy(trDelta, &mut vel);
        }
        crate::q_math::_VectorMA(vel, 80.0, dir, &mut ctx.entity_mut(limb).epVelocity);

        // add some vertical velocity
        if limbType == G2_MODELPART_HEAD as c_int || limbType == G2_MODELPART_WAIST as c_int {
            ctx.entity_mut(limb).epVelocity[2] += 10.0;
        }

        // enemy may be an NPC — `.client` is a pool client, deref stays raw (2b).
        let saber_toss = match enemy {
            Some(enemy_id) => {
                let ecl = ctx.entity(enemy_id).client;
                !ecl.is_null()
                    && ent != enemy_id
                    && ctx.entity(ent).s.number != ctx.entity(enemy_id).s.number
                    && unsafe { (*ecl).ps.weapon } == WP_SABER as c_int
                    && unsafe { (*ecl).olderIsValid } != qfalse
                    && (ctx.world.level.time - unsafe { (*ecl).lastSaberStorageTime }) < 200
            }
            None => false,
        };
        if saber_toss {
            let enemy_id = enemy.unwrap();
            let ecl = ctx.entity(enemy_id).client;
            let mut dif: vec3_t = [0.0; 3];
            let mut totalDistance;
            let distScale: f32 = 1.2;

            // scale down the initial velocity first
            let ev = ctx.entity(limb).epVelocity;
            crate::q_math::_VectorScale(ev, 0.4f32, &mut ctx.entity_mut(limb).epVelocity);

            crate::q_math::_VectorSubtract(
                unsafe { (*ecl).lastSaberBase_Always },
                unsafe { (*ecl).olderSaberBase },
                &mut dif,
            );
            totalDistance = crate::q_math::VectorNormalize(&mut dif);

            crate::q_math::_VectorScale(dif, totalDistance * distScale, &mut dif);
            let ev = ctx.entity(limb).epVelocity;
            crate::q_math::_VectorAdd(ev, dif, &mut ctx.entity_mut(limb).epVelocity);

            if !ent_client.is_null()
                && (unsafe { (*ent_client).ps.torsoTimer } > 0
                    || mp_bg::bg_panimate::BG_InDeathAnim(unsafe { (*ent_client).ps.torsoAnim })
                        == qfalse)
            {
                // if he's done with his death anim we don't actually want the limbs going far
                let mut preVel: vec3_t = [0.0; 3];

                let ev = ctx.entity(limb).epVelocity;
                crate::q_math::_VectorCopy(ev, &mut preVel);
                preVel[2] = 0.0;
                totalDistance = crate::q_math::VectorNormalize(&mut preVel);

                if totalDistance < 40.0 {
                    let mAmt: f32 = 40.0;

                    ctx.entity_mut(limb).epVelocity[0] = preVel[0] * mAmt;
                    ctx.entity_mut(limb).epVelocity[1] = preVel[1] * mAmt;
                }
            } else if !ent_client.is_null() {
                let ev = ctx.entity(limb).epVelocity;
                crate::q_math::_VectorScale(ev, 0.3f32, &mut ctx.entity_mut(limb).epVelocity);
            }
        }

        if ctx.entity(ent).s.eType == entityType_t::ET_NPC as c_int && !ghoul2.is_null() {
            // if it's an npc remove these surfs on the server too.
            trap::G2API_SetSurfaceOnOff(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_SETSURFACEONOFF::GG2SetsurfaceonoffArgs::new(
                    ghoul2,
                    limbName.as_ptr(),
                    0x00000100,
                ),
            );
            trap::G2API_SetSurfaceOnOff(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_SETSURFACEONOFF::GG2SetsurfaceonoffArgs::new(
                    ghoul2,
                    stubCapName.as_ptr(),
                    0,
                ),
            );
        }

        let customRGBA = ctx.entity(ent).s.customRGBA;
        ctx.entity_mut(limb).s.customRGBA[0] = customRGBA[0];
        ctx.entity_mut(limb).s.customRGBA[1] = customRGBA[1];
        ctx.entity_mut(limb).s.customRGBA[2] = customRGBA[2];
        ctx.entity_mut(limb).s.customRGBA[3] = customRGBA[3];

        let limb_ptr = ctx.entity_mut(limb) as *mut gentity_t;
        trap::LinkEntity(
            ctx.engine,
            mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(limb_ptr.cast()),
        );
    }
}

/// Raven `DismembermentTest`.
///
/// Source: `oracle/codemp/game/g_combat.c:3622-3633`
pub fn DismembermentTest(ctx: &mut GameContext, self_: EntityId) {
    use animNumber_t::*;
    use g2ModelParts_t::*;
    let mut sect = G2_MODELPART_HEAD as c_int;
    let mut boltPoint: vec3_t = [0.0; 3];

    while sect <= G2_MODELPART_RLEG as c_int {
        G_GetDismemberBolt(ctx, self_, &mut boltPoint, sect);
        G_Dismember(
            ctx,
            self_,
            Some(self_),
            boltPoint,
            sect,
            90.0,
            0.0,
            BOTH_DEATH1 as c_int,
            qfalse,
        );
        sect += 1;
    }
}

/// Raven `DismembermentByNum`.
///
/// Source: `oracle/codemp/game/g_combat.c:3635-3669`
pub fn DismembermentByNum(ctx: &mut GameContext, self_: EntityId, num: c_int) {
    use animNumber_t::*;
    use g2ModelParts_t::*;
    let mut boltPoint: vec3_t = [0.0; 3];

    let sect = match num {
        0 => G2_MODELPART_HEAD as c_int,
        1 => G2_MODELPART_WAIST as c_int,
        2 => G2_MODELPART_LARM as c_int,
        3 => G2_MODELPART_RARM as c_int,
        4 => G2_MODELPART_RHAND as c_int,
        5 => G2_MODELPART_LLEG as c_int,
        6 => G2_MODELPART_RLEG as c_int,
        _ => G2_MODELPART_HEAD as c_int,
    };

    G_GetDismemberBolt(ctx, self_, &mut boltPoint, sect);
    G_Dismember(
        ctx,
        self_,
        Some(self_),
        boltPoint,
        sect,
        90.0,
        0.0,
        BOTH_DEATH1 as c_int,
        qfalse,
    );
}

/// Raven `G_GetHitQuad`.
///
/// `hitloc` is read-only (subtracted into a local `diff`), so it stays
/// by-value.
/// Source: `oracle/codemp/game/g_combat.c:3671-3751`
pub fn G_GetHitQuad(ctx: &mut GameContext, self_: EntityId, hitloc: vec3_t) -> c_int {
    use g2ModelParts_t::*;
    let mut diff: vec3_t = [0.0; 3];
    let mut fwdangles: vec3_t = [0.0, 0.0, 0.0];
    let mut right: vec3_t = [0.0; 3];
    let mut clEye: vec3_t;
    let mut hitLoc = ctx.world.globals.gPainHitLoc;

    // self_ may be an NPC — `.client` is a pool client, deref stays raw (2b).
    let client = ctx.entity(self_).client;
    if !client.is_null() {
        clEye = unsafe { (*client).ps.origin };
        clEye[2] += unsafe { (*client).ps.viewheight } as f32;
    } else {
        clEye = ctx.entity(self_).s.pos.trBase;
        clEye[2] += 16.0;
    }

    for i in 0..3 {
        diff[i] = hitloc[i] - clEye[i];
    }
    diff[2] = 0.0;
    VectorNormalize(&mut diff);

    if !client.is_null() {
        fwdangles[1] = unsafe { (*client).ps.viewangles[1] };
    } else {
        fwdangles[1] = ctx.entity(self_).s.apos.trBase[1];
    }
    // Ultimately we might care if the shot was ahead or behind, but for now,
    // just quadrant is fine.
    AngleVectors(fwdangles, None, Some(&mut right), None);

    let rightdot = right[0] * diff[0] + right[1] * diff[1] + right[2] * diff[2];
    let zdiff = hitloc[2] - clEye[2];

    if zdiff > 0.0 {
        if (rightdot as f64) > 0.3 {
            hitLoc = G2_MODELPART_RARM as c_int;
        } else if (rightdot as f64) < -0.3 {
            hitLoc = G2_MODELPART_LARM as c_int;
        } else {
            hitLoc = G2_MODELPART_HEAD as c_int;
        }
    } else if zdiff > -20.0 {
        if (rightdot as f64) > 0.1 {
            hitLoc = G2_MODELPART_RARM as c_int;
        } else if (rightdot as f64) < -0.1 {
            hitLoc = G2_MODELPART_LARM as c_int;
        } else {
            hitLoc = G2_MODELPART_HEAD as c_int;
        }
    } else if rightdot >= 0.0 {
        hitLoc = G2_MODELPART_RLEG as c_int;
    } else {
        hitLoc = G2_MODELPART_LLEG as c_int;
    }

    hitLoc
}

/// Raven `G_GetHitLocFromSurfName`.
///
/// Callers encode Raven's NULL `vec3_t point` as the zero vector, so the
/// `if (!point)` guard becomes a zero test (lockstep-caught 2026-07-14).
/// Source: `oracle/codemp/game/g_combat.c:3757-4216`
pub fn G_GetHitLocFromSurfName(
    ctx: &mut GameContext,
    ent: EntityId,
    surfName: *const c_char,
    hitLoc: *mut c_int,
    point: vec3_t,
    dir: vec3_t,
    bladeDir: vec3_t,
    r#mod: c_int,
) -> qboolean {
    // ent's `.client` is a pool client for NPCs (deref raw, trap 2b), `*hitLoc`
    // is a raw out-param, and the ghoul2 bolt-matrix calls take raw field
    // pointers — the body keeps one unsafe scope; ent fields (all reads) route
    // through the accessor.
    unsafe {
        let mut dismember: qboolean = qfalse;
        let mut kneeLBolt: c_int = -1;
        let mut kneeRBolt: c_int = -1;
        let mut handRBolt: c_int = -1;
        let mut handLBolt: c_int = -1;
        let mut footRBolt: c_int = -1;
        let mut footLBolt: c_int = -1;

        *hitLoc = HL_NONE;

        if surfName.is_null() || *surfName == 0 {
            return qfalse;
        }

        let client = ctx.entity(ent).client;
        if client.is_null() {
            return qfalse;
        }
        // Raven `if (!point) return qfalse;` — zero vector is the NULL sentinel.
        if point == [0.0, 0.0, 0.0] {
            return qfalse;
        }

        if !ctx.entity(ent).client.is_null()
            && ((*client).NPC_class == class_t::CLASS_R2D2
                || (*client).NPC_class == class_t::CLASS_R2D2
                || (*client).NPC_class == class_t::CLASS_GONK
                || (*client).NPC_class == class_t::CLASS_MOUSE
                || (*client).NPC_class == class_t::CLASS_SENTRY
                || (*client).NPC_class == class_t::CLASS_INTERROGATOR
                || (*client).NPC_class == class_t::CLASS_SENTRY
                || (*client).NPC_class == class_t::CLASS_PROBE)
        {
            // we don't care about per-surface hit-locations or dismemberment for these guys
            return qfalse;
        }

        if ctx.entity(ent).localAnimIndex <= 1 {
            // humanoid
            handLBolt = trap::G2API_AddBolt(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs::new(
                    ctx.entity(ent).ghoul2,
                    0,
                    c"*l_hand".to_owned(),
                ),
            );
            handRBolt = trap::G2API_AddBolt(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs::new(
                    ctx.entity(ent).ghoul2,
                    0,
                    c"*r_hand".to_owned(),
                ),
            );
            kneeLBolt = trap::G2API_AddBolt(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs::new(
                    ctx.entity(ent).ghoul2,
                    0,
                    c"*hips_l_knee".to_owned(),
                ),
            );
            kneeRBolt = trap::G2API_AddBolt(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs::new(
                    ctx.entity(ent).ghoul2,
                    0,
                    c"*hips_r_knee".to_owned(),
                ),
            );
            footLBolt = trap::G2API_AddBolt(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs::new(
                    ctx.entity(ent).ghoul2,
                    0,
                    c"*l_leg_foot".to_owned(),
                ),
            );
            footRBolt = trap::G2API_AddBolt(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs::new(
                    ctx.entity(ent).ghoul2,
                    0,
                    c"*r_leg_foot".to_owned(),
                ),
            );
        }

        let stricmp = |lit: &CStr| crate::q_shared::Q_stricmp(lit.as_ptr(), surfName) == 0;

        if !ctx.entity(ent).client.is_null() && (*client).NPC_class == class_t::CLASS_ATST {
            if stricmp(c"head_light_blaster_cann") {
                *hitLoc = HL_ARM_LT;
            } else if stricmp(c"head_concussion_charger") {
                *hitLoc = HL_ARM_RT;
            }
            return qfalse;
        } else if !ctx.entity(ent).client.is_null() && (*client).NPC_class == class_t::CLASS_MARK1 {
            if stricmp(c"l_arm") {
                *hitLoc = HL_ARM_LT;
            } else if stricmp(c"r_arm") {
                *hitLoc = HL_ARM_RT;
            } else if stricmp(c"torso_front") {
                *hitLoc = HL_CHEST;
            } else if stricmp(c"torso_tube1") {
                *hitLoc = HL_GENERIC1;
            } else if stricmp(c"torso_tube2") {
                *hitLoc = HL_GENERIC2;
            } else if stricmp(c"torso_tube3") {
                *hitLoc = HL_GENERIC3;
            } else if stricmp(c"torso_tube4") {
                *hitLoc = HL_GENERIC4;
            } else if stricmp(c"torso_tube5") {
                *hitLoc = HL_GENERIC5;
            } else if stricmp(c"torso_tube6") {
                *hitLoc = HL_GENERIC6;
            }
            return qfalse;
        } else if !ctx.entity(ent).client.is_null() && (*client).NPC_class == class_t::CLASS_MARK2 {
            if stricmp(c"torso_canister1") {
                *hitLoc = HL_GENERIC1;
            } else if stricmp(c"torso_canister2") {
                *hitLoc = HL_GENERIC2;
            } else if stricmp(c"torso_canister3") {
                *hitLoc = HL_GENERIC3;
            }
            return qfalse;
        } else if !ctx.entity(ent).client.is_null()
            && (*client).NPC_class == class_t::CLASS_GALAKMECH
        {
            if stricmp(c"torso_antenna") || stricmp(c"torso_antenna_base") {
                *hitLoc = HL_GENERIC1;
            } else if stricmp(c"torso_shield") {
                *hitLoc = HL_GENERIC2;
            } else {
                *hitLoc = HL_CHEST;
            }
            return qfalse;
        }

        let strncmp =
            |lit: &CStr, n: c_int| crate::q_shared::Q_strncmp(lit.as_ptr(), surfName, n) == 0;

        let actualTime = ctx.world.level.time;
        if strncmp(c"hips", 4) {
            // FIXME: test properly for legs
            *hitLoc = HL_WAIST;
            if !ctx.entity(ent).client.is_null() && !ctx.entity(ent).ghoul2.is_null() {
                let mut boltMatrix: mdxaBone_t = core::mem::zeroed();
                let mut tagOrg: vec3_t = [0.0; 3];

                let angles: vec3_t = [0.0, ctx.entity(ent).r.currentAngles[YAW], 0.0];
                if kneeLBolt >= 0 {
                    trap::G2API_GetBoltMatrix(
                        ctx.engine,
                        mp_abi::game::syscalls::G_G2_GETBOLT::GG2GetboltArgs::new(
                            ctx.entity(ent).ghoul2,
                            0,
                            kneeLBolt,
                            &mut boltMatrix as *mut mdxaBone_t,
                            &angles as *const vec3_t,
                            &ctx.entity(ent).r.currentOrigin as *const vec3_t,
                            actualTime,
                            core::ptr::null_mut(),
                            &ctx.entity(ent).modelScale as *const vec3_t,
                        ),
                    );
                    crate::NPC_AI_GalakMech::BG_GiveMeVectorFromMatrix(
                        &boltMatrix as *const mdxaBone_t,
                        ORIGIN as c_int,
                        &mut tagOrg,
                    );
                    if crate::q_math::DistanceSquared(point, tagOrg) < 100.0 {
                        *hitLoc = HL_LEG_LT; // actually hit the knee
                    }
                }
                if *hitLoc == HL_WAIST {
                    if kneeRBolt >= 0 {
                        trap::G2API_GetBoltMatrix(
                            ctx.engine,
                            mp_abi::game::syscalls::G_G2_GETBOLT::GG2GetboltArgs::new(
                                ctx.entity(ent).ghoul2,
                                0,
                                kneeRBolt,
                                &mut boltMatrix as *mut mdxaBone_t,
                                &angles as *const vec3_t,
                                &ctx.entity(ent).r.currentOrigin as *const vec3_t,
                                actualTime,
                                core::ptr::null_mut(),
                                &ctx.entity(ent).modelScale as *const vec3_t,
                            ),
                        );
                        crate::NPC_AI_GalakMech::BG_GiveMeVectorFromMatrix(
                            &boltMatrix as *const mdxaBone_t,
                            ORIGIN as c_int,
                            &mut tagOrg,
                        );
                        if crate::q_math::DistanceSquared(point, tagOrg) < 100.0 {
                            *hitLoc = HL_LEG_RT; // actually hit the knee
                        }
                    }
                }
            }
        } else if strncmp(c"torso", 5) {
            if ctx.entity(ent).client.is_null() {
                *hitLoc = HL_CHEST;
            } else {
                let mut t_fwd: vec3_t = [0.0; 3];
                let mut t_rt: vec3_t = [0.0; 3];
                let mut t_up: vec3_t = [0.0; 3];
                let mut dirToImpact: vec3_t = [0.0; 3];
                AngleVectors(
                    (*client).renderInfo.torsoAngles,
                    Some(&mut t_fwd),
                    Some(&mut t_rt),
                    Some(&mut t_up),
                );

                if (*client).renderInfo.boltValidityTime != ctx.world.level.time {
                    let renderAng: vec3_t = [0.0, (*client).ps.viewangles[YAW], 0.0];
                    let origin = (*client).ps.origin;
                    crate::w_saber::UpdateClientRenderBolts(ctx, ent, origin, renderAng);
                }

                crate::q_math::_VectorSubtract(
                    point,
                    (*client).renderInfo.torsoPoint,
                    &mut dirToImpact,
                );
                let frontSide = crate::q_math::_DotProduct(t_fwd, dirToImpact);
                let rightSide = crate::q_math::_DotProduct(t_rt, dirToImpact);
                let upSide = crate::q_math::_DotProduct(t_up, dirToImpact);
                if upSide < -10.0 {
                    *hitLoc = HL_WAIST; // hit at waist
                } else {
                    // hit on upper torso
                    if rightSide > 4.0 {
                        *hitLoc = HL_ARM_RT;
                    } else if rightSide < -4.0 {
                        *hitLoc = HL_ARM_LT;
                    } else if rightSide > 2.0 {
                        if frontSide > 0.0 {
                            *hitLoc = HL_CHEST_RT;
                        } else {
                            *hitLoc = HL_BACK_RT;
                        }
                    } else if rightSide < -2.0 {
                        if frontSide > 0.0 {
                            *hitLoc = HL_CHEST_LT;
                        } else {
                            *hitLoc = HL_BACK_LT;
                        }
                    } else if upSide > -3.0 && r#mod == meansOfDeath_t::MOD_SABER as c_int {
                        *hitLoc = HL_HEAD;
                    } else if frontSide > 0.0 {
                        *hitLoc = HL_CHEST;
                    } else {
                        *hitLoc = HL_BACK;
                    }
                }
            }
        } else if strncmp(c"head", 4) {
            *hitLoc = HL_HEAD;
        } else if strncmp(c"r_arm", 5) {
            *hitLoc = HL_ARM_RT;
            if !ctx.entity(ent).client.is_null() && !ctx.entity(ent).ghoul2.is_null() {
                let mut boltMatrix: mdxaBone_t = core::mem::zeroed();
                let mut tagOrg: vec3_t = [0.0; 3];
                let angles: vec3_t = [0.0, ctx.entity(ent).r.currentAngles[YAW], 0.0];
                if handRBolt >= 0 {
                    trap::G2API_GetBoltMatrix(
                        ctx.engine,
                        mp_abi::game::syscalls::G_G2_GETBOLT::GG2GetboltArgs::new(
                            ctx.entity(ent).ghoul2,
                            0,
                            handRBolt,
                            &mut boltMatrix as *mut mdxaBone_t,
                            &angles as *const vec3_t,
                            &ctx.entity(ent).r.currentOrigin as *const vec3_t,
                            actualTime,
                            core::ptr::null_mut(),
                            &ctx.entity(ent).modelScale as *const vec3_t,
                        ),
                    );
                    crate::NPC_AI_GalakMech::BG_GiveMeVectorFromMatrix(
                        &boltMatrix as *const mdxaBone_t,
                        ORIGIN as c_int,
                        &mut tagOrg,
                    );
                    if crate::q_math::DistanceSquared(point, tagOrg) < 256.0 {
                        *hitLoc = HL_HAND_RT; // actually hit the hand
                    }
                }
            }
        } else if strncmp(c"l_arm", 5) {
            *hitLoc = HL_ARM_LT;
            if !ctx.entity(ent).client.is_null() && !ctx.entity(ent).ghoul2.is_null() {
                let mut boltMatrix: mdxaBone_t = core::mem::zeroed();
                let mut tagOrg: vec3_t = [0.0; 3];
                let angles: vec3_t = [0.0, ctx.entity(ent).r.currentAngles[YAW], 0.0];
                if handLBolt >= 0 {
                    trap::G2API_GetBoltMatrix(
                        ctx.engine,
                        mp_abi::game::syscalls::G_G2_GETBOLT::GG2GetboltArgs::new(
                            ctx.entity(ent).ghoul2,
                            0,
                            handLBolt,
                            &mut boltMatrix as *mut mdxaBone_t,
                            &angles as *const vec3_t,
                            &ctx.entity(ent).r.currentOrigin as *const vec3_t,
                            actualTime,
                            core::ptr::null_mut(),
                            &ctx.entity(ent).modelScale as *const vec3_t,
                        ),
                    );
                    crate::NPC_AI_GalakMech::BG_GiveMeVectorFromMatrix(
                        &boltMatrix as *const mdxaBone_t,
                        ORIGIN as c_int,
                        &mut tagOrg,
                    );
                    if crate::q_math::DistanceSquared(point, tagOrg) < 256.0 {
                        *hitLoc = HL_HAND_LT; // actually hit the hand
                    }
                }
            }
        } else if strncmp(c"r_leg", 5) {
            *hitLoc = HL_LEG_RT;
            if !ctx.entity(ent).client.is_null() && !ctx.entity(ent).ghoul2.is_null() {
                let mut boltMatrix: mdxaBone_t = core::mem::zeroed();
                let mut tagOrg: vec3_t = [0.0; 3];
                let angles: vec3_t = [0.0, ctx.entity(ent).r.currentAngles[YAW], 0.0];
                if footRBolt >= 0 {
                    trap::G2API_GetBoltMatrix(
                        ctx.engine,
                        mp_abi::game::syscalls::G_G2_GETBOLT::GG2GetboltArgs::new(
                            ctx.entity(ent).ghoul2,
                            0,
                            footRBolt,
                            &mut boltMatrix as *mut mdxaBone_t,
                            &angles as *const vec3_t,
                            &ctx.entity(ent).r.currentOrigin as *const vec3_t,
                            actualTime,
                            core::ptr::null_mut(),
                            &ctx.entity(ent).modelScale as *const vec3_t,
                        ),
                    );
                    crate::NPC_AI_GalakMech::BG_GiveMeVectorFromMatrix(
                        &boltMatrix as *const mdxaBone_t,
                        ORIGIN as c_int,
                        &mut tagOrg,
                    );
                    if crate::q_math::DistanceSquared(point, tagOrg) < 100.0 {
                        *hitLoc = HL_FOOT_RT; // actually hit the foot
                    }
                }
            }
        } else if strncmp(c"l_leg", 5) {
            *hitLoc = HL_LEG_LT;
            if !ctx.entity(ent).client.is_null() && !ctx.entity(ent).ghoul2.is_null() {
                let mut boltMatrix: mdxaBone_t = core::mem::zeroed();
                let mut tagOrg: vec3_t = [0.0; 3];
                let angles: vec3_t = [0.0, ctx.entity(ent).r.currentAngles[YAW], 0.0];
                if footLBolt >= 0 {
                    trap::G2API_GetBoltMatrix(
                        ctx.engine,
                        mp_abi::game::syscalls::G_G2_GETBOLT::GG2GetboltArgs::new(
                            ctx.entity(ent).ghoul2,
                            0,
                            footLBolt,
                            &mut boltMatrix as *mut mdxaBone_t,
                            &angles as *const vec3_t,
                            &ctx.entity(ent).r.currentOrigin as *const vec3_t,
                            actualTime,
                            core::ptr::null_mut(),
                            &ctx.entity(ent).modelScale as *const vec3_t,
                        ),
                    );
                    crate::NPC_AI_GalakMech::BG_GiveMeVectorFromMatrix(
                        &boltMatrix as *const mdxaBone_t,
                        ORIGIN as c_int,
                        &mut tagOrg,
                    );
                    if crate::q_math::DistanceSquared(point, tagOrg) < 100.0 {
                        *hitLoc = HL_FOOT_LT; // actually hit the foot
                    }
                }
            }
        } else if strncmp(c"r_hand", 6) || strncmp(c"w_", 2) {
            // right hand or weapon
            *hitLoc = HL_HAND_RT;
        } else if strncmp(c"l_hand", 6) {
            *hitLoc = HL_HAND_LT;
        }

        if ctx.world.cvars.g_dismember.integer == 100 {
            // full probability...
            if !ctx.entity(ent).client.is_null() && (*client).NPC_class == class_t::CLASS_PROTOCOL {
                dismember = qtrue;
            } else if (dir[0] != 0.0 || dir[1] != 0.0 || dir[2] != 0.0)
                && (bladeDir[0] != 0.0 || bladeDir[1] != 0.0 || bladeDir[2] != 0.0)
            {
                // we care about direction (presumably for dismemberment)
                if true {
                    // Fix me?
                    let mut tagName: *const c_char = core::ptr::null();
                    let mut aoa: f32 = 0.5;
                    // dir must be roughly perpendicular to the hitLoc's cap bolt
                    let hl = *hitLoc;
                    if hl == HL_LEG_RT {
                        tagName = c"*hips_cap_r_leg".as_ptr();
                    } else if hl == HL_LEG_LT {
                        tagName = c"*hips_cap_l_leg".as_ptr();
                    } else if hl == HL_WAIST {
                        tagName = c"*hips_cap_torso".as_ptr();
                        aoa = 0.25;
                    } else if hl == HL_CHEST_RT || hl == HL_ARM_RT || hl == HL_BACK_LT {
                        tagName = c"*torso_cap_r_arm".as_ptr();
                    } else if hl == HL_CHEST_LT || hl == HL_ARM_LT || hl == HL_BACK_RT {
                        tagName = c"*torso_cap_l_arm".as_ptr();
                    } else if hl == HL_HAND_RT {
                        tagName = c"*r_arm_cap_r_hand".as_ptr();
                    } else if hl == HL_HAND_LT {
                        tagName = c"*l_arm_cap_l_hand".as_ptr();
                    } else if hl == HL_HEAD {
                        tagName = c"*torso_cap_head".as_ptr();
                        aoa = 0.25;
                    }
                    // HL_CHEST/HL_BACK/HL_FOOT_RT/HL_FOOT_LT/default: no dismemberment possible

                    if !tagName.is_null() {
                        let tagBolt = trap::G2API_AddBolt(
                            ctx.engine,
                            mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs::new(
                                ctx.entity(ent).ghoul2,
                                0,
                                core::ffi::CStr::from_ptr(tagName).to_owned(),
                            ),
                        );
                        if tagBolt != -1 {
                            let mut boltMatrix: mdxaBone_t = core::mem::zeroed();
                            let mut tagOrg: vec3_t = [0.0; 3];
                            let mut tagDir: vec3_t = [0.0; 3];
                            let angles: vec3_t = [0.0, ctx.entity(ent).r.currentAngles[YAW], 0.0];

                            trap::G2API_GetBoltMatrix(
                                ctx.engine,
                                mp_abi::game::syscalls::G_G2_GETBOLT::GG2GetboltArgs::new(
                                    ctx.entity(ent).ghoul2,
                                    0,
                                    tagBolt,
                                    &mut boltMatrix as *mut mdxaBone_t,
                                    &angles as *const vec3_t,
                                    &ctx.entity(ent).r.currentOrigin as *const vec3_t,
                                    actualTime,
                                    core::ptr::null_mut(),
                                    &ctx.entity(ent).modelScale as *const vec3_t,
                                ),
                            );
                            crate::NPC_AI_GalakMech::BG_GiveMeVectorFromMatrix(
                                &boltMatrix as *const mdxaBone_t,
                                ORIGIN as c_int,
                                &mut tagOrg,
                            );
                            crate::NPC_AI_GalakMech::BG_GiveMeVectorFromMatrix(
                                &boltMatrix as *const mdxaBone_t,
                                NEGATIVE_Y as c_int,
                                &mut tagDir,
                            );
                            if crate::q_math::DistanceSquared(point, tagOrg) < 256.0 {
                                // hit close
                                let mut dot = crate::q_math::_DotProduct(dir, tagDir);
                                if dot < aoa && dot > -aoa {
                                    // hit roughly perpendicular
                                    dot = crate::q_math::_DotProduct(bladeDir, tagDir);
                                    if dot < aoa && dot > -aoa {
                                        // blade was roughly perpendicular
                                        dismember = qtrue;
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                // hmm, no direction supplied.
                dismember = qtrue;
            }
        }
        dismember
    }
}

/// Raven `G_CheckForDismemberment`.
///
/// Source: `oracle/codemp/game/g_combat.c:4218-4344`
pub fn G_CheckForDismemberment(
    ctx: &mut GameContext,
    ent: EntityId,
    enemy: Option<EntityId>,
    point: vec3_t,
    damage: c_int,
    deathAnim: c_int,
    postDeath: qboolean,
) {
    use g2ModelParts_t::*;
    // ent's `.client` is a pool client for NPCs (deref raw, trap 2b); the body
    // keeps one unsafe scope. Entity fields (all reads) route through the
    // accessor.
    unsafe {
        let mut hitLoc: c_int = -1;
        let mut hitLocUse: c_int;
        let mut boltPoint: vec3_t = [0.0; 3];
        let dismember = ctx.world.cvars.g_dismember.integer;
        let client = ctx.entity(ent).client;

        if ctx.entity(ent).localAnimIndex > 1 {
            if ctx.entity(ent).NPC.is_null() {
                return;
            }

            if (*client).NPC_class != class_t::CLASS_PROTOCOL {
                // this is the only non-humanoid allowed to do dismemberment.
                return;
            }
        }

        if dismember == 0 {
            return;
        }

        if ctx.world.globals.gGAvoidDismember == 1 {
            return;
        }

        if ctx.world.globals.gGAvoidDismember != 2 {
            // this means do the dismemberment regardless of randomness and damage
            if ctx.world.bg_state.rng.Q_irand(0, 100) > dismember {
                return;
            }

            if damage < 5 {
                return;
            }
        }

        if ctx.world.globals.gGAvoidDismember == 2 {
            hitLoc = HL_HAND_RT;
        } else {
            if ctx.world.cvars.d_saberGhoul2Collision.integer != 0
                && !ctx.entity(ent).client.is_null()
                && (*client).g2LastSurfaceTime == ctx.world.level.time
            {
                let mut hitSurface: [c_char; MAX_QPATH as usize] = [0; MAX_QPATH as usize];

                trap::G2API_GetSurfaceName(
                    ctx.engine,
                    mp_abi::game::syscalls::G_G2_GETSURFACENAME::GG2GetsurfacenameArgs::new(
                        ctx.entity(ent).ghoul2,
                        (*client).g2LastSurfaceHit,
                        0,
                        hitSurface.as_mut_ptr(),
                    ),
                );

                if hitSurface[0] != 0 {
                    G_GetHitLocFromSurfName(
                        ctx,
                        ent,
                        hitSurface.as_ptr(),
                        &mut hitLoc,
                        point,
                        [0.0; 3],
                        [0.0; 3],
                        meansOfDeath_t::MOD_UNKNOWN as c_int,
                    );
                }
            }

            if hitLoc == -1 {
                hitLoc = G_GetHitLocation(ctx, ent, point);
            }
        }

        hitLocUse = match hitLoc {
            HL_FOOT_RT | HL_LEG_RT => G2_MODELPART_RLEG as c_int,
            HL_FOOT_LT | HL_LEG_LT => G2_MODELPART_LLEG as c_int,
            HL_WAIST => G2_MODELPART_WAIST as c_int,
            HL_ARM_RT => G2_MODELPART_RARM as c_int,
            HL_HAND_RT => G2_MODELPART_RHAND as c_int,
            HL_ARM_LT | HL_HAND_LT => G2_MODELPART_LARM as c_int,
            HL_HEAD => G2_MODELPART_HEAD as c_int,
            _ => G_GetHitQuad(ctx, ent, point),
        };

        if hitLocUse == -1 {
            return;
        }

        if !ctx.entity(ent).client.is_null() {
            G_GetDismemberBolt(ctx, ent, &mut boltPoint, hitLocUse);
            if ctx.world.cvars.g_austrian.integer != 0
                && (ctx.world.cvars.g_gametype.integer == GT_DUEL
                    || ctx.world.cvars.g_gametype.integer == GT_POWERDUEL)
            {
                let s = format!(
                    "Duel Dismemberment: {} dismembered at {}\n",
                    cstr_to_str((*client).pers.netname.as_ptr()),
                    cstr_to_str(hitLocName[hitLoc as usize].as_ptr())
                );
                crate::g_main::G_LogPrintf(ctx, cstr(&s).as_ptr());
            }
        } else {
            G_GetDismemberLoc(ctx.entity(ent), &mut boltPoint, hitLocUse);
        }
        G_Dismember(
            ctx, ent, enemy, boltPoint, hitLocUse, 90.0, 0.0, deathAnim, postDeath,
        );
    }
}

/// Raven `G_LocationBasedDamageModifier`.
///
/// Source: `oracle/codemp/game/g_combat.c:4346-4425`
pub fn G_LocationBasedDamageModifier(
    ctx: &mut GameContext,
    ent: EntityId,
    point: vec3_t,
    r#mod: c_int,
    dflags: c_int,
    damage: *mut c_int,
) {
    // ent's `.client` is a pool client for NPCs (deref raw, trap 2b), `*damage`
    // is a raw out-param; the body keeps one unsafe scope. Entity fields (all
    // reads) route through the accessor.
    unsafe {
        let mut hitLoc: c_int = -1;
        let client = ctx.entity(ent).client;

        if ctx.world.cvars.g_locationBasedDamage.integer == 0 {
            // then leave it alone
            return;
        }

        if (dflags & DAMAGE_NO_HIT_LOC) != 0 {
            // then leave it alone
            return;
        }

        if r#mod == meansOfDeath_t::MOD_SABER as c_int && *damage <= 1 {
            // don't bother for idle damage
            return;
        }
        // Raven `if (!point) return;` — zero vector is the NULL sentinel.
        if point == [0.0, 0.0, 0.0] {
            return;
        }

        if !ctx.entity(ent).client.is_null() && (*client).NPC_class == class_t::CLASS_VEHICLE {
            // no location-based damage on vehicles
            return;
        }

        if (ctx.world.cvars.d_saberGhoul2Collision.integer != 0
            && !ctx.entity(ent).client.is_null()
            && (*client).g2LastSurfaceTime == ctx.world.level.time
            && r#mod == meansOfDeath_t::MOD_SABER as c_int)
            || (ctx.world.cvars.d_projectileGhoul2Collision.integer != 0
                && !ctx.entity(ent).client.is_null()
                && (*client).g2LastSurfaceTime == ctx.world.level.time)
        {
            let mut hitSurface: [c_char; MAX_QPATH as usize] = [0; MAX_QPATH as usize];

            trap::G2API_GetSurfaceName(
                ctx.engine,
                mp_abi::game::syscalls::G_G2_GETSURFACENAME::GG2GetsurfacenameArgs::new(
                    ctx.entity(ent).ghoul2,
                    (*client).g2LastSurfaceHit,
                    0,
                    hitSurface.as_mut_ptr(),
                ),
            );

            if hitSurface[0] != 0 {
                G_GetHitLocFromSurfName(
                    ctx,
                    ent,
                    hitSurface.as_ptr(),
                    &mut hitLoc,
                    point,
                    [0.0; 3],
                    [0.0; 3],
                    meansOfDeath_t::MOD_UNKNOWN as c_int,
                );
            }
        }

        if hitLoc == -1 {
            hitLoc = G_GetHitLocation(ctx, ent, point);
        }

        match hitLoc {
            HL_FOOT_RT | HL_FOOT_LT => {
                *damage = (*damage as f64 * 0.5) as c_int;
            }
            HL_LEG_RT | HL_LEG_LT => {
                *damage = (*damage as f64 * 0.7) as c_int;
            }
            HL_WAIST | HL_BACK_RT | HL_BACK_LT | HL_BACK | HL_CHEST_RT | HL_CHEST_LT | HL_CHEST => {
                // normal damage
            }
            HL_ARM_RT | HL_ARM_LT => {
                *damage = (*damage as f64 * 0.85) as c_int;
            }
            HL_HAND_RT | HL_HAND_LT => {
                *damage = (*damage as f64 * 0.6) as c_int;
            }
            HL_HEAD => {
                *damage = (*damage as f64 * 1.3) as c_int;
            }
            _ => {
                // do nothing then
            }
        }
    }
}

/// Raven `G_ThereIsAMaster`.
///
/// Source: `oracle/codemp/game/g_combat.c:4432-4450`
pub fn G_ThereIsAMaster(ctx: &mut GameContext) -> qboolean {
    for i in 0..MAX_CLIENTS as usize {
        // real client slot (i < MAX_CLIENTS); deref raw (trap 2b).
        let client = ctx.world.g_entities[i].client;
        if !client.is_null() && unsafe { (*client).ps.isJediMaster } != qfalse {
            return qtrue;
        }
    }
    qfalse
}

/// Raven `G_Knockdown`.
///
/// Source: `oracle/codemp/game/g_combat.c:4452-4461`
pub fn G_Knockdown(ctx: &mut GameContext, victim: Option<EntityId>) {
    let Some(victim) = victim else {
        return;
    };
    // victim may be an NPC — `.client` is a pool client, deref stays raw (2b).
    let client = ctx.entity(victim).client;
    if !client.is_null() {
        unsafe {
            if BG_KnockDownable(&mut (*client).ps as *mut playerState_t) != qfalse {
                (*client).ps.forceHandExtend = HANDEXTEND_KNOCKDOWN as c_int;
                (*client).ps.forceDodgeAnim = 0;
                (*client).ps.forceHandExtendTime = ctx.world.level.time + 1100;
                (*client).ps.quickerGetup = qfalse;
            }
        }
    }
}

/// Raven `G_ApplyVehicleOtherKiller`.
///
/// Source: `oracle/codemp/game/g_combat.c:4463-4526`
pub fn G_ApplyVehicleOtherKiller(
    ctx: &mut GameContext,
    targ: Option<EntityId>,
    inflictor: Option<EntityId>,
    attacker: Option<EntityId>,
    r#mod: c_int,
    vehicleDying: qboolean,
) {
    // targ/pilot/passenger `.client` are pool clients and the vehicle-struct
    // derefs (m_pVehicle, m_pPilot, m_ppPassengers) stay raw (traps 2b/2c); the
    // body keeps one unsafe scope. Entity fields route through the accessor.
    let (Some(targ), Some(attacker)) = (targ, attacker) else {
        return;
    };
    let targClient = ctx.entity(targ).client;
    if targClient.is_null() {
        return;
    }
    let targVeh = ctx.entity(targ).m_pVehicle;
    unsafe {
        if (*targClient).ps.otherKillerDebounceTime > ctx.world.level.time {
            // wait a minute, I already have a last damager
            if ctx.entity(targ).health < 0
                || (!ctx.entity(targ).m_pVehicle.is_null() && (*targVeh).m_iRemovedSurfaces != 0)
            {
                // already dying?  don't let credit transfer to anyone else
                return;
            }
            // otherwise, still alive, so, fine, use this damager...
        }

        let attacker_number = ctx.entity(attacker).s.number;
        (*targClient).ps.otherKiller = attacker_number;
        (*targClient).ps.otherKillerTime = ctx.world.level.time + 25000;
        (*targClient).ps.otherKillerDebounceTime = ctx.world.level.time + 25000;
        (*targClient).otherKillerMOD = r#mod;
        if inflictor.is_some_and(|inf| {
            crate::q_shared::Q_stricmp(c"vehicle_proj".as_ptr(), ctx.entity(inf).classname) == 0
        }) {
            let inf = inflictor.unwrap();
            (*targClient).otherKillerVehWeapon = ctx.entity(inf).s.otherEntityNum2 + 1;
            (*targClient).otherKillerWeaponType = ctx.entity(inf).s.weapon;
        } else {
            (*targClient).otherKillerVehWeapon = 0;
            (*targClient).otherKillerWeaponType = WP_NONE as c_int;
        }
        if vehicleDying != qfalse {
            // propogate otherkiller down to pilot and passengers
            if !ctx.entity(targ).m_pVehicle.is_null() {
                if !(*targVeh).m_pPilot.is_null() {
                    let pilot_num = (*((*targVeh).m_pPilot as *mut gentity_t)).s.number;
                    let pilot = EntityId(pilot_num as u32);
                    let pc = ctx.entity(pilot).client;
                    if !pc.is_null() {
                        (*pc).ps.otherKiller = (*targClient).ps.otherKiller;
                        (*pc).ps.otherKillerTime = (*targClient).ps.otherKillerTime;
                        (*pc).ps.otherKillerDebounceTime = (*targClient).ps.otherKillerDebounceTime;
                        (*pc).otherKillerMOD = (*targClient).otherKillerMOD;
                        (*pc).otherKillerVehWeapon = (*targClient).otherKillerVehWeapon;
                        (*pc).otherKillerWeaponType = (*targClient).otherKillerWeaponType;
                    }
                }
                let mut passNum = 0;
                while passNum < (*targVeh).m_iNumPassengers {
                    let pass_num = (*((*targVeh).m_ppPassengers[passNum as usize]
                        as *mut gentity_t))
                        .s
                        .number;
                    let pass = EntityId(pass_num as u32);
                    let pc = ctx.entity(pass).client;
                    if !pc.is_null() {
                        (*pc).ps.otherKiller = (*targClient).ps.otherKiller;
                        (*pc).ps.otherKillerTime = (*targClient).ps.otherKillerTime;
                        (*pc).ps.otherKillerDebounceTime = (*targClient).ps.otherKillerDebounceTime;
                        (*pc).otherKillerMOD = (*targClient).otherKillerMOD;
                        (*pc).otherKillerVehWeapon = (*targClient).otherKillerVehWeapon;
                        (*pc).otherKillerWeaponType = (*targClient).otherKillerWeaponType;
                    }
                    passNum += 1;
                }
            }
        }
    }
}

/// Raven `G_CheckVehicleNPCTeamDamage`.
///
/// Raven: NOTE: this covers both the vehicle and NPCs riding vehicles (droids).
/// Source: `oracle/codemp/game/g_combat.c:4528-4544`
pub fn G_CheckVehicleNPCTeamDamage(ent: Option<&gentity_t>) -> qboolean {
    // not valid or a real client or not an NPC
    let Some(ent) = ent else {
        return qfalse;
    };
    if ent.s.number < MAX_CLIENTS as c_int || ent.s.eType != entityType_t::ET_NPC as c_int {
        return qfalse;
    }

    if ent.s.NPC_class != class_t::CLASS_VEHICLE as c_int {
        // regular NPC
        if ent.s.m_iVehicleNum != 0 {
            // an NPC in a vehicle, check for team damage
            return qtrue;
        }
    }
    qfalse
}

/// Raven `G_Damage`.
///
/// Source: `oracle/codemp/game/g_combat.c:4577-5715`
pub fn G_Damage(
    ctx: &mut GameContext,
    targ: Option<EntityId>,
    inflictor: Option<EntityId>,
    attacker: Option<EntityId>,
    mut dir: Option<&mut vec3_t>,
    point: vec3_t,
    mut damage: c_int,
    mut dflags: c_int,
    r#mod: c_int,
) {
    // STAGE-1: Option params (body null-checks all three), raw re-derived
    // verbatim (Stage-2 debt); mega-fn — the G_Damage hub.
    unsafe {
        let base = ctx.world.g_entities.as_mut_ptr();
        let targ: *mut gentity_t = crate::ent_id::resolve(base, targ);
        let mut inflictor: *mut gentity_t = crate::ent_id::resolve(base, inflictor);
        let mut attacker: *mut gentity_t = crate::ent_id::resolve(base, attacker);
        let mut take: c_int;
        let mut save: c_int;
        let asave: c_int;
        let mut knockback: c_int;
        let max: c_int;
        let mut subamt: c_int = 0;
        let mut famt: f32 = 0.0;
        let mut hamt: f32 = 0.0;
        let mut shieldAbsorbed: f32 = 0.0;

        if !targ.is_null() && (*targ).damageRedirect != qfalse {
            G_Damage(
                ctx,
                EntityId::from_num((*targ).damageRedirectTo),
                ctx.entity_id_of(inflictor),
                ctx.entity_id_of(attacker),
                dir.as_deref_mut(),
                point,
                damage,
                dflags,
                r#mod,
            );
            return;
        }

        if r#mod == meansOfDeath_t::MOD_DEMP2 as c_int
            && !targ.is_null()
            && (*targ).inuse != qfalse
            && !(*targ).client.is_null()
        {
            let tc = (*targ).client;
            let tv = (*targ).m_pVehicle;
            if (*tc).ps.electrifyTime < ctx.world.level.time {
                // electrocution effect
                if (*targ).s.eType == entityType_t::ET_NPC as c_int
                    && (*targ).s.NPC_class == class_t::CLASS_VEHICLE as c_int
                    && !(*targ).m_pVehicle.is_null()
                    && ((*(*tv).m_pVehicleInfo).r#type == VH_SPEEDER
                        || (*(*tv).m_pVehicleInfo).r#type == VH_WALKER)
                {
                    // do some extra stuff to speeders/walkers
                    (*tc).ps.electrifyTime =
                        ctx.world.level.time + ctx.world.bg_state.rng.Q_irand(3000, 4000);
                } else if (*targ).s.NPC_class != class_t::CLASS_VEHICLE as c_int
                    || (!(*targ).m_pVehicle.is_null()
                        && (*(*tv).m_pVehicleInfo).r#type != VH_FIGHTER)
                {
                    // don't do this to fighters
                    (*tc).ps.electrifyTime =
                        ctx.world.level.time + ctx.world.bg_state.rng.Q_irand(300, 800);
                }
            }
        }

        if ctx.world.cvars.g_gametype.integer == GT_SIEGE && ctx.world.globals.gSiegeRoundBegun == 0
        {
            // nothing can be damaged til the round starts.
            return;
        }

        if (*targ).takedamage == qfalse {
            return;
        }

        if ((*targ).flags & FL_SHIELDED) != 0
            && r#mod != meansOfDeath_t::MOD_SABER as c_int
            && (*targ).client.is_null()
        {
            // magnetically protected, this thing can only be damaged by lightsabers
            return;
        }

        if ((*targ).flags & FL_DMG_BY_SABER_ONLY) != 0
            && r#mod != meansOfDeath_t::MOD_SABER as c_int
        {
            // saber-only damage
            return;
        }

        if !(*targ).client.is_null() {
            // don't take damage when in a walker, or fighter unless it's dead
            let tc = (*targ).client;
            if (*tc).ps.clientNum < MAX_CLIENTS as c_int && (*tc).ps.m_iVehicleNum != 0 {
                let veh =
                    &mut ctx.world.g_entities[(*tc).ps.m_iVehicleNum as usize] as *mut gentity_t;
                let vv = (*veh).m_pVehicle;
                if !(*veh).m_pVehicle.is_null() && (*veh).health > 0 {
                    if (*(*vv).m_pVehicleInfo).r#type == VH_WALKER
                        || (*(*vv).m_pVehicleInfo).r#type == VH_FIGHTER
                    {
                        if (dflags & DAMAGE_NO_PROTECTION) == 0 {
                            return;
                        }
                    }
                }
            }
        }

        if ((*targ).flags & FL_DMG_BY_HEAVY_WEAP_ONLY) != 0 {
            // only take damage from explosives and such
            let m = r#mod;
            use meansOfDeath_t::*;
            if m != MOD_REPEATER_ALT as c_int
                && m != MOD_ROCKET as c_int
                && m != MOD_FLECHETTE_ALT_SPLASH as c_int
                && m != MOD_ROCKET_HOMING as c_int
                && m != MOD_THERMAL as c_int
                && m != MOD_THERMAL_SPLASH as c_int
                && m != MOD_TRIP_MINE_SPLASH as c_int
                && m != MOD_TIMED_MINE_SPLASH as c_int
                && m != MOD_DET_PACK_SPLASH as c_int
                && m != MOD_VEHICLE as c_int
                && m != MOD_CONC as c_int
                && m != MOD_CONC_ALT as c_int
                && m != MOD_SABER as c_int
                && m != MOD_TURBLAST as c_int
                && m != MOD_TARGET_LASER as c_int
                && m != MOD_SUICIDE as c_int
                && m != MOD_FALLING as c_int
                && m != MOD_CRUSH as c_int
                && m != MOD_TELEFRAG as c_int
                && m != MOD_COLLISION as c_int
                && m != MOD_VEH_EXPLOSION as c_int
                && m != MOD_TRIGGER_HURT as c_int
            {
                if r#mod != MOD_MELEE as c_int
                    || G_HeavyMelee(ctx, ctx.entity_id_of(attacker)) == qfalse
                {
                    // let classes with heavy melee ability damage heavy wpn dmg doors with fists
                    return;
                }
            }
        }

        if ((*targ).flags & FL_BBRUSH) != 0 {
            use meansOfDeath_t::*;
            if r#mod == MOD_DEMP2 as c_int
                || r#mod == MOD_DEMP2_ALT as c_int
                || r#mod == MOD_BRYAR_PISTOL as c_int
                || r#mod == MOD_BRYAR_PISTOL_ALT as c_int
                || r#mod == MOD_MELEE as c_int
            {
                // these don't damage bbrushes.. ever
                if r#mod != MOD_MELEE as c_int
                    || G_HeavyMelee(ctx, ctx.entity_id_of(attacker)) == qfalse
                {
                    // let classes with heavy melee ability damage breakable brushes with fists
                    return;
                }
            }
        }

        if !targ.is_null()
            && !(*targ).client.is_null()
            && (*((*targ).client)).ps.duelInProgress != 0
        {
            let tc = (*targ).client;
            if !attacker.is_null()
                && !(*attacker).client.is_null()
                && (*attacker).s.number != (*tc).ps.duelIndex
            {
                return;
            } else if !attacker.is_null()
                && !(*attacker).client.is_null()
                && r#mod != meansOfDeath_t::MOD_SABER as c_int
            {
                return;
            }
        }
        if !attacker.is_null()
            && !(*attacker).client.is_null()
            && (*((*attacker).client)).ps.duelInProgress != 0
        {
            let ac = (*attacker).client;
            if !targ.is_null()
                && !(*targ).client.is_null()
                && (*targ).s.number != (*ac).ps.duelIndex
            {
                return;
            } else if !targ.is_null()
                && !(*targ).client.is_null()
                && r#mod != meansOfDeath_t::MOD_SABER as c_int
            {
                return;
            }
        }

        if (dflags & DAMAGE_NO_PROTECTION) == 0 {
            // rage overridden by no_protection
            if !targ.is_null()
                && !(*targ).client.is_null()
                && ((*((*targ).client)).ps.fd.forcePowersActive & (1 << FP_RAGE as c_int)) != 0
            {
                damage = (damage as f64 * 0.5) as c_int;
            }
        }

        // the intermission has already been qualified for
        if ctx.world.level.intermissionQueued != 0 {
            return;
        }
        if inflictor.is_null() {
            inflictor = &mut ctx.world.g_entities[ENTITYNUM_WORLD as usize] as *mut gentity_t;
        }
        if attacker.is_null() {
            attacker = &mut ctx.world.g_entities[ENTITYNUM_WORLD as usize] as *mut gentity_t;
        }

        // shootable doors / buttons don't actually have any health
        if (*targ).s.eType == entityType_t::ET_MOVER as c_int && (*targ).genericValue4 != 1 {
            if (*targ).use_.is_some() && (*targ).moverState == MOVER_POS1 {
                crate::g_utils::GlobalUse(
                    ctx,
                    ctx.entity_id_of(targ),
                    ctx.entity_id_of(inflictor),
                    ctx.entity_id_of(attacker),
                );
            }
            return;
        }
        // reduce damage by the attacker's handicap value unless they are rocket jumping
        if !(*attacker).client.is_null()
            && attacker != targ
            && (*attacker).s.eType == entityType_t::ET_PLAYER as c_int
            && ctx.world.cvars.g_gametype.integer != GT_SIEGE
        {
            max = (*((*attacker).client)).ps.stats[statIndex_t::STAT_MAX_HEALTH as usize];
            damage = damage * max / 100;
        }

        if (dflags & DAMAGE_NO_HIT_LOC) == 0 {
            // see if we should modify it by damage location
            if (*targ).inuse != qfalse
                && (!(*targ).client.is_null() || (*targ).s.eType == entityType_t::ET_NPC as c_int)
                && (*attacker).inuse != qfalse
                && (!(*attacker).client.is_null()
                    || (*attacker).s.eType == entityType_t::ET_NPC as c_int)
            {
                G_LocationBasedDamageModifier(
                    ctx,
                    ctx.entity_id_of(targ).unwrap(),
                    point,
                    r#mod,
                    dflags,
                    &mut damage,
                );
            }
        }

        if !(*targ).client.is_null()
            && (*((*targ).client)).NPC_class == class_t::CLASS_RANCOR
            && (attacker.is_null()
                || (*attacker).client.is_null()
                || (*((*attacker).client)).NPC_class != class_t::CLASS_RANCOR)
        {
            // I guess always do 10 points of damage
            if damage < 10 {
                damage = 0;
            } else if damage >= 10 {
                damage = 10;
            }
        }

        let client = (*targ).client;

        if !client.is_null() {
            if (*client).noclip != qfalse {
                return;
            }
        }

        // Raven `if (!dir) dflags|=DAMAGE_NO_KNOCKBACK; else VectorNormalize(dir);`
        if let Some(d) = dir.as_deref_mut() {
            crate::q_math::VectorNormalize(d);
        } else {
            dflags |= DAMAGE_NO_KNOCKBACK;
        }
        // Snapshot the (now-normalized) direction and its presence for the read
        // sites below. `dir_val` is zero when NULL; those reads are gated by
        // DAMAGE_NO_KNOCKBACK or an explicit `dir_present` branch (Raven §19: the
        // one NULL-deref path — DirToByte — becomes DirToByte(vec3_origin)).
        let dir_present = dir.is_some();
        let dir_val: vec3_t = dir.as_deref().copied().unwrap_or([0.0, 0.0, 0.0]);

        knockback = damage;
        if knockback > 200 {
            knockback = 200;
        }
        if ((*targ).flags & FL_NO_KNOCKBACK) != 0 {
            knockback = 0;
        }
        if (dflags & DAMAGE_NO_KNOCKBACK) != 0 {
            knockback = 0;
        }

        // figure momentum add, even if the damage won't be taken
        if knockback != 0 && !(*targ).client.is_null() {
            let mut kvel: vec3_t = [0.0; 3];
            let mass: f32 = 200.0;
            let tc = (*targ).client;
            let g_knockback = ctx.world.cvars.g_knockback.value;

            if r#mod == meansOfDeath_t::MOD_SABER as c_int {
                let mut saberKnockbackScale = ctx.world.cvars.g_saberDmgVelocityScale.value;
                if (dflags & DAMAGE_SABER_KNOCKBACK1) != 0
                    || (dflags & DAMAGE_SABER_KNOCKBACK2) != 0
                {
                    if saberKnockbackScale == 0.0 {
                        saberKnockbackScale = 1.0;
                    }
                    if !attacker.is_null() && !(*attacker).client.is_null() {
                        let ac = (*attacker).client;
                        if (dflags & DAMAGE_SABER_KNOCKBACK1) != 0 {
                            saberKnockbackScale *= (*ac).saber[0].knockbackScale;
                        }
                        if (dflags & DAMAGE_SABER_KNOCKBACK1_B2) != 0 {
                            saberKnockbackScale *= (*ac).saber[0].knockbackScale2;
                        }
                        if (dflags & DAMAGE_SABER_KNOCKBACK2) != 0 {
                            saberKnockbackScale *= (*ac).saber[1].knockbackScale;
                        }
                        if (dflags & DAMAGE_SABER_KNOCKBACK2_B2) != 0 {
                            saberKnockbackScale *= (*ac).saber[1].knockbackScale2;
                        }
                    }
                }
                crate::q_math::_VectorScale(
                    dir_val,
                    (g_knockback * knockback as f32 / mass) * saberKnockbackScale,
                    &mut kvel,
                );
            } else {
                crate::q_math::_VectorScale(
                    dir_val,
                    g_knockback * knockback as f32 / mass,
                    &mut kvel,
                );
            }
            crate::q_math::_VectorAdd((*tc).ps.velocity, kvel, &mut (*tc).ps.velocity);

            // set the timer so that the other client can't cancel out the movement immediately
            if (*tc).ps.pm_time == 0
                && (ctx.world.cvars.g_saberDmgVelocityScale.integer != 0
                    || r#mod != meansOfDeath_t::MOD_SABER as c_int
                    || (dflags & DAMAGE_SABER_KNOCKBACK1) != 0
                    || (dflags & DAMAGE_SABER_KNOCKBACK2) != 0
                    || (dflags & DAMAGE_SABER_KNOCKBACK1_B2) != 0
                    || (dflags & DAMAGE_SABER_KNOCKBACK2_B2) != 0)
            {
                let mut t = knockback * 2;
                if t < 50 {
                    t = 50;
                }
                if t > 200 {
                    t = 200;
                }
                (*tc).ps.pm_time = t;
                (*tc).ps.pm_flags |= PMF_TIME_KNOCKBACK;
            }
        }

        if (ctx.world.cvars.g_trueJedi.integer != 0
            || ctx.world.cvars.g_gametype.integer == GT_SIEGE)
            && !client.is_null()
        {
            // less explosive damage for jedi, more saber damage for non-jedi
            use meansOfDeath_t::*;
            if (*client).ps.trueJedi != 0
                || (ctx.world.cvars.g_gametype.integer == GT_SIEGE
                    && (*client).ps.weapon == WP_SABER as c_int)
            {
                // reduce splash and explosive damage to 1/2
                let m = r#mod;
                if m == MOD_REPEATER_ALT as c_int
                    || m == MOD_REPEATER_ALT_SPLASH as c_int
                    || m == MOD_DEMP2_ALT as c_int
                    || m == MOD_FLECHETTE_ALT_SPLASH as c_int
                    || m == MOD_ROCKET as c_int
                    || m == MOD_ROCKET_SPLASH as c_int
                    || m == MOD_ROCKET_HOMING as c_int
                    || m == MOD_ROCKET_HOMING_SPLASH as c_int
                    || m == MOD_THERMAL as c_int
                    || m == MOD_THERMAL_SPLASH as c_int
                    || m == MOD_TRIP_MINE_SPLASH as c_int
                    || m == MOD_TIMED_MINE_SPLASH as c_int
                    || m == MOD_DET_PACK_SPLASH as c_int
                {
                    damage = (damage as f64 * 0.75) as c_int;
                }
            } else if ((*client).ps.trueNonJedi != 0
                || (ctx.world.cvars.g_gametype.integer == GT_SIEGE
                    && (*client).ps.weapon != WP_SABER as c_int))
                && r#mod == MOD_SABER as c_int
            {
                // trueNonJedi takes more saber damage
                if damage < 100 {
                    damage *= 4;
                    if damage > 100 {
                        damage = 100;
                    }
                }
            }
        }

        if !(*attacker).client.is_null()
            && !(*targ).client.is_null()
            && ctx.world.cvars.g_gametype.integer == GT_SIEGE
            && (*((*targ).client)).siegeClass != -1
            && ((&ctx.world.bg_state.bgSiegeClasses)[(*((*targ).client)).siegeClass as usize]
                .classflags
                & (1 << CFL_STRONGAGAINSTPHYSICAL as c_int))
                != 0
        {
            // this class takes less damage from physical attacks.
            damage = (damage as f64 * 0.5) as c_int;
        }

        // check for completely getting out of the damage
        if (dflags & DAMAGE_NO_PROTECTION) == 0 {
            if targ != attacker {
                if crate::g_team::OnSameTeam(
                    ctx,
                    ctx.entity_id_of(targ),
                    ctx.entity_id_of(attacker),
                ) != qfalse
                {
                    if ctx.world.cvars.g_friendlyFire.integer == 0 {
                        return;
                    }
                } else if !attacker.is_null()
                    && (*attacker).inuse != qfalse
                    && (*attacker).client.is_null()
                    && (*attacker).activator.is_some()
                    && {
                        let act = &mut ctx.world.g_entities
                            [(*attacker).activator.unwrap().0 as usize]
                            as *mut gentity_t;
                        targ != act && (*act).inuse != qfalse && !(*act).client.is_null()
                    }
                {
                    // emplaced guns don't hurt teammates of user
                    let act = &mut ctx.world.g_entities[(*attacker).activator.unwrap().0 as usize]
                        as *mut gentity_t;
                    if crate::g_team::OnSameTeam(ctx, ctx.entity_id_of(targ), ctx.entity_id_of(act))
                        != qfalse
                    {
                        if ctx.world.cvars.g_friendlyFire.integer == 0 {
                            return;
                        }
                    }
                } else if (*targ).inuse != qfalse
                    && !(*targ).client.is_null()
                    && ctx.world.cvars.g_gametype.integer >= GT_TEAM
                    && (*attacker).s.number >= MAX_CLIENTS as c_int
                    && (*attacker).alliedTeam != 0
                    && (*((*targ).client)).sess.sessionTeam == (*attacker).alliedTeam
                    && ctx.world.cvars.g_friendlyFire.integer == 0
                {
                    // things allied with my team shouldn't hurt me
                    return;
                }
            }

            if ctx.world.cvars.g_gametype.integer == GT_JEDIMASTER
                && ctx.world.cvars.g_friendlyFire.integer == 0
                && !targ.is_null()
                && !(*targ).client.is_null()
                && !attacker.is_null()
                && !(*attacker).client.is_null()
                && targ != attacker
                && (*((*targ).client)).ps.isJediMaster == qfalse
                && (*((*attacker).client)).ps.isJediMaster == qfalse
                && G_ThereIsAMaster(ctx) != qfalse
            {
                return;
            }

            if (*targ).s.number >= MAX_CLIENTS as c_int
                && !(*targ).client.is_null()
                && (*targ).s.shouldtarget != qfalse
                && (*targ).s.teamowner != 0
                && !attacker.is_null()
                && (*attacker).inuse != qfalse
                && !(*attacker).client.is_null()
                && (*targ).s.owner >= 0
                && (*targ).s.owner < MAX_CLIENTS as c_int
            {
                let targown = &mut ctx.world.g_entities[(*targ).s.owner as usize] as *mut gentity_t;

                if !targown.is_null()
                    && (*targown).inuse != qfalse
                    && !(*targown).client.is_null()
                    && crate::g_team::OnSameTeam(
                        ctx,
                        ctx.entity_id_of(targown),
                        ctx.entity_id_of(attacker),
                    ) != qfalse
                {
                    if ctx.world.cvars.g_friendlyFire.integer == 0 {
                        return;
                    }
                }
            }

            // check for godmode
            if ((*targ).flags & FL_GODMODE) != 0 && (*targ).s.eType != entityType_t::ET_NPC as c_int
            {
                return;
            }

            if !targ.is_null()
                && !(*targ).client.is_null()
                && ((*((*targ).client)).ps.eFlags & EF_INVULNERABLE) != 0
                && !attacker.is_null()
                && !(*attacker).client.is_null()
                && targ != attacker
            {
                let tc = (*targ).client;
                if (*tc).invulnerableTimer <= ctx.world.level.time {
                    (*tc).ps.eFlags &= !EF_INVULNERABLE;
                } else {
                    return;
                }
            }
        }

        // check for teamnodmg
        if !attacker.is_null() && (*targ).client.is_null() {
            // attacker hit a non-client
            if ctx.world.cvars.g_gametype.integer == GT_SIEGE
                && ctx.world.cvars.g_ff_objectives.integer == 0
            {
                if (*targ).teamnodmg != 0 {
                    // targ shouldn't take damage from a certain team
                    if !(*attacker).client.is_null() {
                        // a client hit a non-client object
                        if (*targ).teamnodmg == (*((*attacker).client)).sess.sessionTeam {
                            return;
                        }
                    } else if (*attacker).teamnodmg != 0 {
                        // a non-client hit a non-client object
                        if (*targ).teamnodmg == (*attacker).teamnodmg {
                            if (*attacker).activator.is_some() && {
                                let a = &mut ctx.world.g_entities
                                    [(*attacker).activator.unwrap().0 as usize]
                                    as *mut gentity_t;
                                (*a).inuse != qfalse
                                    && (*a).s.number < MAX_CLIENTS as c_int
                                    && !(*a).client.is_null()
                                    && (*((*a).client)).sess.sessionTeam != (*targ).teamnodmg
                            } {
                                // uh, let them damage it I guess.
                            } else {
                                return;
                            }
                        }
                    }
                }
            }
        }

        // battlesuit protects from all radius damage (but takes knockback) and 50% against all damage
        if !client.is_null() && (*client).ps.powerups[PW_BATTLESUIT as usize] != 0 {
            G_AddEvent(
                &mut *(targ),
                entity_event_t::EV_POWERUP_BATTLESUIT as c_int,
                0,
            );
            if (dflags & DAMAGE_RADIUS) != 0 || r#mod == meansOfDeath_t::MOD_FALLING as c_int {
                return;
            }
            damage = (damage as f64 * 0.5) as c_int;
        }

        // add to the attacker's hit counter
        if !(*attacker).client.is_null()
            && targ != attacker
            && (*targ).health > 0
            && (*targ).s.eType != entityType_t::ET_MISSILE as c_int
            && (*targ).s.eType != entityType_t::ET_GENERAL as c_int
            && !client.is_null()
        {
            let ac = (*attacker).client;
            if crate::g_team::OnSameTeam(ctx, ctx.entity_id_of(targ), ctx.entity_id_of(attacker))
                != qfalse
            {
                (*ac).ps.persistant[persEnum_t::PERS_HITS as usize] -= 1;
            } else {
                (*ac).ps.persistant[persEnum_t::PERS_HITS as usize] += 1;
            }
            (*ac).ps.persistant[persEnum_t::PERS_ATTACKEE_ARMOR as usize] =
                ((*targ).health << 8) | ((*client).ps.stats[statIndex_t::STAT_ARMOR as usize]);
        }

        // always give half damage if hurting self... but not in siege.
        if targ == attacker && (dflags & DAMAGE_NO_SELF_PROTECTION) == 0 {
            if ctx.world.cvars.g_gametype.integer == GT_SIEGE {
                damage = (damage as f64 * 1.5) as c_int;
            } else {
                damage = (damage as f64 * 0.5) as c_int;
            }
        }

        if damage < 1 {
            damage = 1;
        }

        // store the attacker as the potential killer in case we die by other means
        if !(*targ).client.is_null() && !attacker.is_null() && attacker != targ {
            let tc = (*targ).client;
            if (*targ).s.eType == entityType_t::ET_NPC as c_int
                && (*targ).s.NPC_class == class_t::CLASS_VEHICLE as c_int
            {
                // vehicle
                G_ApplyVehicleOtherKiller(
                    ctx,
                    ctx.entity_id_of(targ),
                    ctx.entity_id_of(inflictor),
                    ctx.entity_id_of(attacker),
                    r#mod,
                    qfalse,
                );
            } else {
                // other client
                (*tc).ps.otherKiller = (*attacker).s.number;
                (*tc).ps.otherKillerTime = ctx.world.level.time + 5000;
                (*tc).ps.otherKillerDebounceTime = ctx.world.level.time + 100;
                (*tc).otherKillerMOD = r#mod;
                (*tc).otherKillerVehWeapon = 0;
                (*tc).otherKillerWeaponType = WP_NONE as c_int;
            }
        }

        take = damage;
        save = 0;

        // save some from armor
        asave = CheckArmor(ctx, ctx.entity_id_of(targ).unwrap(), take, dflags);

        if asave != 0 {
            shieldAbsorbed = asave as f32;
        }

        take -= asave;
        if !(*targ).client.is_null() {
            // update vehicle shields and armor, check for explode
            let tc = (*targ).client;
            let tv = (*targ).m_pVehicle;
            if (*tc).NPC_class == class_t::CLASS_VEHICLE && !(*targ).m_pVehicle.is_null() {
                let mut surface: c_int = -1;
                if !attacker.is_null() {
                    // so we know the last guy who shot at us
                    (*targ).enemy = Some(ent_id(base, attacker));
                }

                (*tv).m_iShields = (*tc).ps.stats[statIndex_t::STAT_ARMOR as usize];
                crate::g_vehicles::G_VehUpdateShields(&mut *targ);
                (*tv).m_iArmor -= take;
                if (*tv).m_iArmor <= 0 {
                    (*targ).s.eFlags |= EF_DEAD;
                    (*tc).ps.eFlags |= EF_DEAD;
                    (*tv).m_iArmor = 0;
                }
                if (*(*tv).m_pVehicleInfo).r#type == VH_FIGHTER {
                    // get the last surf that was hit
                    if !(*targ).client.is_null() && (*tc).g2LastSurfaceTime == ctx.world.level.time
                    {
                        let mut hitSurface: [c_char; MAX_QPATH as usize] = [0; MAX_QPATH as usize];

                        trap::G2API_GetSurfaceName(
                            ctx.engine,
                            mp_abi::game::syscalls::G_G2_GETSURFACENAME::GG2GetsurfacenameArgs::new(
                                (*targ).ghoul2,
                                (*tc).g2LastSurfaceHit,
                                0,
                                hitSurface.as_mut_ptr(),
                            ),
                        );

                        if hitSurface[0] != 0 {
                            surface =
                                crate::g_vehicles::G_ShipSurfaceForSurfName(hitSurface.as_ptr());

                            if take != 0 && surface > 0 {
                                // hit a certain part of the ship
                                let mut deathPoint: c_int = 0;

                                (*targ).locationDamage[surface as usize] += take;

                                match surface {
                                    SHIPSURF_FRONT => {
                                        deathPoint = (*(*tv).m_pVehicleInfo).health_front;
                                    }
                                    SHIPSURF_BACK => {
                                        deathPoint = (*(*tv).m_pVehicleInfo).health_back;
                                    }
                                    SHIPSURF_RIGHT => {
                                        deathPoint = (*(*tv).m_pVehicleInfo).health_right;
                                    }
                                    SHIPSURF_LEFT => {
                                        deathPoint = (*(*tv).m_pVehicleInfo).health_left;
                                    }
                                    _ => {}
                                }

                                if deathPoint != 0 {
                                    if (*targ).locationDamage[surface as usize] >= deathPoint {
                                        // this area of the ship is now dead
                                        let wasDying = (*tv).m_iRemovedSurfaces != 0;
                                        if crate::g_vehicles::G_FlyVehicleDestroySurface(
                                            ctx,
                                            ctx.entity_id_of(targ).unwrap(),
                                            surface,
                                        ) != qfalse
                                        {
                                            crate::g_vehicles::G_VehicleSetDamageLocFlags(
                                                ctx,
                                                ctx.entity_id_of(targ).unwrap(),
                                                surface,
                                                deathPoint,
                                            );
                                            if !wasDying {
                                                (*tc).ps.otherKillerDebounceTime = 0;
                                            }
                                            G_ApplyVehicleOtherKiller(
                                                ctx,
                                                ctx.entity_id_of(targ),
                                                ctx.entity_id_of(inflictor),
                                                ctx.entity_id_of(attacker),
                                                r#mod,
                                                qtrue,
                                            );
                                        }
                                    } else {
                                        crate::g_vehicles::G_VehicleSetDamageLocFlags(
                                            ctx,
                                            ctx.entity_id_of(targ).unwrap(),
                                            surface,
                                            deathPoint,
                                        );
                                    }
                                }
                            }
                        }
                    }
                }
                if (*(*tv).m_pVehicleInfo).r#type != VH_ANIMAL {
                    if !attacker.is_null()
                        && targ != attacker
                        && crate::q_math::VectorCompare((*tc).ps.origin, point) == qfalse
                        && (*tv).m_LandTrace.fraction >= 1.0
                    {
                        // just took a hit, knock us around
                        let mut vUp: vec3_t = [0.0; 3];
                        let mut impactDir: vec3_t = [0.0; 3];
                        let mut impactStrength = (damage as f32 / 200.0) * 10.0;
                        let mut dot: f32;
                        if impactStrength > 10.0 {
                            impactStrength = 10.0;
                        }
                        // pitch or roll us based on where we were hit
                        AngleVectors(
                            *((*tv).m_vOrientation as *const vec3_t),
                            None,
                            None,
                            Some(&mut vUp),
                        );
                        crate::q_math::_VectorSubtract(
                            point,
                            (*targ).r.currentOrigin,
                            &mut impactDir,
                        );
                        crate::q_math::VectorNormalize(&mut impactDir);
                        if surface <= 0 {
                            // no surf guess where we were hit, then
                            let mut vFwd: vec3_t = [0.0; 3];
                            let mut vRight: vec3_t = [0.0; 3];
                            AngleVectors(
                                *((*tv).m_vOrientation as *const vec3_t),
                                Some(&mut vFwd),
                                Some(&mut vRight),
                                Some(&mut vUp),
                            );
                            dot = crate::q_math::_DotProduct(vRight, impactDir);
                            if dot > 0.4 {
                                surface = SHIPSURF_RIGHT;
                            } else if dot < -0.4 {
                                surface = SHIPSURF_LEFT;
                            } else {
                                dot = crate::q_math::_DotProduct(vFwd, impactDir);
                                if dot > 0.0 {
                                    surface = SHIPSURF_FRONT;
                                } else {
                                    surface = SHIPSURF_BACK;
                                }
                            }
                        }
                        match surface {
                            SHIPSURF_FRONT => {
                                dot = crate::q_math::_DotProduct(vUp, impactDir);
                                if dot > 0.0 {
                                    *(*tv).m_vOrientation.add(PITCH) += impactStrength;
                                } else {
                                    *(*tv).m_vOrientation.add(PITCH) -= impactStrength;
                                }
                            }
                            SHIPSURF_BACK => {
                                dot = crate::q_math::_DotProduct(vUp, impactDir);
                                if dot > 0.0 {
                                    *(*tv).m_vOrientation.add(PITCH) -= impactStrength;
                                } else {
                                    *(*tv).m_vOrientation.add(PITCH) += impactStrength;
                                }
                            }
                            SHIPSURF_RIGHT => {
                                dot = crate::q_math::_DotProduct(vUp, impactDir);
                                if dot > 0.0 {
                                    *(*tv).m_vOrientation.add(ROLL) -= impactStrength;
                                } else {
                                    *(*tv).m_vOrientation.add(ROLL) += impactStrength;
                                }
                            }
                            SHIPSURF_LEFT => {
                                dot = crate::q_math::_DotProduct(vUp, impactDir);
                                if dot > 0.0 {
                                    *(*tv).m_vOrientation.add(ROLL) += impactStrength;
                                } else {
                                    *(*tv).m_vOrientation.add(ROLL) -= impactStrength;
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
        }

        if r#mod == meansOfDeath_t::MOD_DEMP2 as c_int
            || r#mod == meansOfDeath_t::MOD_DEMP2_ALT as c_int
        {
            if !client.is_null() {
                let tv = (*targ).m_pVehicle;
                if (*client).NPC_class == class_t::CLASS_VEHICLE
                    && !(*targ).m_pVehicle.is_null()
                    && !(*tv).m_pVehicleInfo.is_null()
                    && (*(*tv).m_pVehicleInfo).r#type == VH_FIGHTER
                {
                    // all damage goes into the disruption of shields and systems
                    take = 0;
                } else {
                    if (*client).jetPackOn != qfalse {
                        // disable jetpack temporarily
                        crate::g_items::Jetpack_Off(&mut *targ);
                        (*client).jetPackToggleTime =
                            ctx.world.level.time + ctx.world.bg_state.rng.Q_irand(3000, 10000);
                    }

                    if (*client).NPC_class == class_t::CLASS_PROTOCOL
                        || (*client).NPC_class == class_t::CLASS_SEEKER
                        || (*client).NPC_class == class_t::CLASS_R2D2
                        || (*client).NPC_class == class_t::CLASS_R5D2
                        || (*client).NPC_class == class_t::CLASS_MOUSE
                        || (*client).NPC_class == class_t::CLASS_GONK
                    {
                        take *= 2;
                    } else if (*client).NPC_class == class_t::CLASS_PROBE
                        || (*client).NPC_class == class_t::CLASS_INTERROGATOR
                        || (*client).NPC_class == class_t::CLASS_MARK1
                        || (*client).NPC_class == class_t::CLASS_MARK2
                        || (*client).NPC_class == class_t::CLASS_SENTRY
                        || (*client).NPC_class == class_t::CLASS_ATST
                    {
                        take *= 5;
                    } else {
                        if take > 0 {
                            take /= 3;
                            if take < 1 {
                                take = 1;
                            }
                        }
                    }
                }
            }
        }

        if ctx.world.cvars.g_debugDamage.integer != 0 {
            let s = format!(
                "{}: client:{} health:{} damage:{} armor:{}\n",
                ctx.world.level.time,
                (*targ).s.number,
                (*targ).health,
                take,
                asave
            );
            crate::g_main::G_Printf(ctx, cstr(&s).as_ptr());
        }

        // add to the damage inflicted on a player this frame
        if !client.is_null() {
            if !attacker.is_null() {
                (*client).ps.persistant[persEnum_t::PERS_ATTACKER as usize] = (*attacker).s.number;
            } else {
                (*client).ps.persistant[persEnum_t::PERS_ATTACKER as usize] = ENTITYNUM_WORLD;
            }
            (*client).damage_armor += asave;
            (*client).damage_blood += take;
            (*client).damage_knockback += knockback;
            // Raven `if (dir) { VectorCopy(dir, damage_from); fromWorld=qfalse }
            // else { VectorCopy(targ->r.currentOrigin, damage_from); fromWorld=qtrue }`.
            if dir_present {
                crate::q_math::_VectorCopy(dir_val, &mut (*client).damage_from);
                (*client).damage_fromWorld = qfalse;
            } else {
                crate::q_math::_VectorCopy((*targ).r.currentOrigin, &mut (*client).damage_from);
                (*client).damage_fromWorld = qtrue;
            }

            if !attacker.is_null() && !(*attacker).client.is_null() {
                crate::ai_main::BotDamageNotification(
                    ctx,
                    ctx.entity_id_of(targ).unwrap(),
                    ctx.entity_id_of(attacker),
                );
            } else if !inflictor.is_null() && !(*inflictor).client.is_null() {
                crate::ai_main::BotDamageNotification(
                    ctx,
                    ctx.entity_id_of(targ).unwrap(),
                    ctx.entity_id_of(inflictor),
                );
            }
        }

        // See if it's the player hurting the enemy flag carrier
        if ctx.world.cvars.g_gametype.integer == GT_CTF
            || ctx.world.cvars.g_gametype.integer == GT_CTY
        {
            crate::g_team::Team_CheckHurtCarrier(
                ctx,
                ctx.entity_id_of(targ),
                ctx.entity_id_of(attacker),
            );
        }

        if !(*targ).client.is_null() {
            // set the last client who damaged the target
            let tc = (*targ).client;
            (*tc).lasthurt_client = (*attacker).s.number;
            (*tc).lasthurt_mod = r#mod;
        }

        if (dflags & DAMAGE_NO_PROTECTION) == 0 {
            if take != 0
                && !(*targ).client.is_null()
                && ((*((*targ).client)).ps.fd.forcePowersActive & (1 << FP_PROTECT as c_int)) != 0
            {
                let tc = (*targ).client;
                if (*tc).ps.fd.forcePower != 0 {
                    let mut maxtake = take;

                    if (*tc).forcePowerSoundDebounce < ctx.world.level.time {
                        crate::w_force::G_PreDefSound(
                            ctx,
                            (*tc).ps.origin,
                            (PDSOUND_PROTECTHIT) as i32,
                        );
                        (*tc).forcePowerSoundDebounce = ctx.world.level.time + 400;
                    }

                    if (*tc).ps.fd.forcePowerLevel[FP_PROTECT as usize] == FORCE_LEVEL_1 {
                        famt = 1.0;
                        hamt = 0.40;
                        if maxtake > 100 {
                            maxtake = 100;
                        }
                    } else if (*tc).ps.fd.forcePowerLevel[FP_PROTECT as usize] == FORCE_LEVEL_2 {
                        famt = 0.5;
                        hamt = 0.60;
                        if maxtake > 200 {
                            maxtake = 200;
                        }
                    } else if (*tc).ps.fd.forcePowerLevel[FP_PROTECT as usize] == FORCE_LEVEL_3 {
                        famt = 0.25;
                        hamt = 0.80;
                        if maxtake > 400 {
                            maxtake = 400;
                        }
                    }

                    if (*tc).ps.powerups[PW_FORCE_BOON as usize] == 0 {
                        (*tc).ps.fd.forcePower =
                            ((*tc).ps.fd.forcePower as f32 - (maxtake as f32 * famt)) as c_int;
                    } else {
                        (*tc).ps.fd.forcePower = ((*tc).ps.fd.forcePower as f32
                            - (maxtake as f32 * famt) / 2.0)
                            as c_int;
                    }
                    subamt = ((maxtake as f32 * hamt) + (take - maxtake) as f32) as c_int;
                    if (*tc).ps.fd.forcePower < 0 {
                        subamt += (*tc).ps.fd.forcePower;
                        (*tc).ps.fd.forcePower = 0;
                    }
                    if subamt != 0 {
                        take -= subamt;

                        if take < 0 {
                            take = 0;
                        }
                    }
                }
            }
        }

        if shieldAbsorbed != 0.0 {
            let evEnt = G_TempEntity(
                ctx,
                (*targ).r.currentOrigin,
                entity_event_t::EV_SHIELD_HIT as c_int,
            );
            (*evEnt).s.otherEntityNum = (*targ).s.number;
            // Raven passes `dir` here even when it may be NULL
            // (would UB-deref); `dir_val` is the zero vector when absent.
            (*evEnt).s.eventParm = crate::q_math::DirToByte(dir_val);
            (*evEnt).s.time2 = shieldAbsorbed as c_int;
        }

        // do the damage
        if take != 0 {
            if !(*targ).client.is_null()
                && (*targ).s.number < MAX_CLIENTS as c_int
                && (r#mod == meansOfDeath_t::MOD_DEMP2 as c_int
                    || r#mod == meansOfDeath_t::MOD_DEMP2_ALT as c_int)
            {
                let tc = (*targ).client;
                if (*tc).ps.weaponTime <= 0 {
                    (*tc).ps.weaponTime = 2000;
                    (*tc).ps.electrifyTime = ctx.world.level.time + 2000;
                    if (*tc).ps.weaponstate == WEAPON_CHARGING as c_int
                        || (*tc).ps.weaponstate == WEAPON_CHARGING_ALT as c_int
                    {
                        (*tc).ps.weaponstate = WEAPON_READY as c_int;
                    }
                }
            }

            if (dflags & DAMAGE_NO_PROTECTION) == 0 {
                if !(*targ).client.is_null()
                    && ((*((*targ).client)).ps.fd.forcePowersActive & (1 << FP_RAGE as c_int)) != 0
                    && (!(*inflictor).client.is_null() || !(*attacker).client.is_null())
                {
                    let tc = (*targ).client;
                    take /= (*tc).ps.fd.forcePowerLevel[FP_RAGE as usize] + 1;
                }
            }
            (*targ).health = (*targ).health - take;

            if ((*targ).flags & FL_UNDYING) != 0 {
                if (*targ).health < 1 {
                    (*targ).health = 1;
                }
            }

            if !(*targ).client.is_null() {
                (*((*targ).client)).ps.stats[statIndex_t::STAT_HEALTH as usize] = (*targ).health;
            }

            if (dflags & DAMAGE_NO_PROTECTION) == 0 {
                if !(*targ).client.is_null()
                    && ((*((*targ).client)).ps.fd.forcePowersActive & (1 << FP_RAGE as c_int)) != 0
                    && (!(*inflictor).client.is_null() || !(*attacker).client.is_null())
                {
                    let tc = (*targ).client;
                    if (*targ).health <= 0 {
                        (*targ).health = 1;
                    }
                    if (*tc).ps.stats[statIndex_t::STAT_HEALTH as usize] <= 0 {
                        (*tc).ps.stats[statIndex_t::STAT_HEALTH as usize] = 1;
                    }
                }
            }

            // We want to set gPainHitLoc regardless of if we have a pain func
            if !(*targ).client.is_null()
                && !(*targ).ghoul2.is_null()
                && (*((*targ).client)).g2LastSurfaceTime == ctx.world.level.time
            {
                let tc = (*targ).client;
                let mut hitSurface: [c_char; MAX_QPATH as usize] = [0; MAX_QPATH as usize];

                trap::G2API_GetSurfaceName(
                    ctx.engine,
                    mp_abi::game::syscalls::G_G2_GETSURFACENAME::GG2GetsurfacenameArgs::new(
                        (*targ).ghoul2,
                        (*tc).g2LastSurfaceHit,
                        0,
                        hitSurface.as_mut_ptr(),
                    ),
                );

                if hitSurface[0] != 0 {
                    let targ_eid = ctx.entity_id_of(targ).unwrap();
                    // STAGE-2b: irreducible — &mut world.globals.gPainHitLoc out-param aliases the ctx passed to the same G_GetHitLocFromSurfName call.
                    let hit_loc_out = &mut (*ctx.world_raw()).globals.gPainHitLoc;
                    G_GetHitLocFromSurfName(
                        ctx,
                        targ_eid,
                        hitSurface.as_ptr(),
                        hit_loc_out,
                        point,
                        dir_val,
                        [0.0; 3],
                        r#mod,
                    );
                } else {
                    ctx.world.globals.gPainHitLoc = -1;
                }

                if ctx.world.globals.gPainHitLoc < (crate::entity::hit_location::HL_MAX) as i32
                    && ctx.world.globals.gPainHitLoc >= 0
                    && (*targ).locationDamage[ctx.world.globals.gPainHitLoc as usize] < Q3_INFINITE
                    && ((*targ).s.eType == entityType_t::ET_PLAYER as c_int
                        || (*targ).s.NPC_class != class_t::CLASS_VEHICLE as c_int)
                {
                    (*targ).locationDamage[ctx.world.globals.gPainHitLoc as usize] += take;

                    if ctx.world.cvars.g_armBreakage.integer != 0
                        && (*tc).ps.brokenLimbs == 0
                        && (*tc).ps.stats[statIndex_t::STAT_HEALTH as usize] > 0
                        && (*targ).health > 0
                        && ((*targ).s.eFlags & EF_DEAD) == 0
                    {
                        if (*targ).locationDamage[HL_ARM_RT as usize]
                            + (*targ).locationDamage[HL_HAND_RT as usize]
                            >= 80
                        {
                            crate::g_client::G_BreakArm(
                                ctx,
                                ctx.entity_id_of(targ).unwrap(),
                                (BROKENLIMB_RARM) as i32,
                            );
                        } else if (*targ).locationDamage[HL_ARM_LT as usize]
                            + (*targ).locationDamage[HL_HAND_LT as usize]
                            >= 80
                        {
                            crate::g_client::G_BreakArm(
                                ctx,
                                ctx.entity_id_of(targ).unwrap(),
                                (BROKENLIMB_LARM) as i32,
                            );
                        }
                    }
                }
            } else {
                ctx.world.globals.gPainHitLoc = -1;
            }

            if (*targ).maxHealth != 0 {
                crate::g_utils::G_ScaleNetHealth(&mut *(targ));
            }

            if (*targ).health <= 0 {
                if !client.is_null() {
                    (*targ).flags |= FL_NO_KNOCKBACK;

                    // Raven `if (point) ... else VectorCopy(ps.origin, pos1)` —
                    // zero vector is the NULL sentinel (no-point deaths, e.g.
                    // falling, record the victim's origin for the death anim).
                    if point != [0.0, 0.0, 0.0] {
                        crate::q_math::_VectorCopy(point, &mut (*targ).pos1);
                    } else {
                        crate::q_math::_VectorCopy(
                            (*((*targ).client)).ps.origin,
                            &mut (*targ).pos1,
                        );
                    }
                } else if (*targ).s.eType == entityType_t::ET_NPC as c_int {
                    // g2animent
                    crate::q_math::_VectorCopy(point, &mut (*targ).pos1);
                }

                if (*targ).health < -999 {
                    (*targ).health = -999;
                }

                // If we are a breaking glass brush, store the damage point
                if ((*targ).r.svFlags & SVF_GLASS_BRUSH) != 0 {
                    crate::q_math::_VectorCopy(point, &mut (*targ).pos1);
                    // Raven `if (dir) VectorCopy(dir,pos2); else VectorClear(pos2);`
                    if dir_present {
                        crate::q_math::_VectorCopy(dir_val, &mut (*targ).pos2);
                    } else {
                        (*targ).pos2 = [0.0, 0.0, 0.0];
                    }
                }

                if (*targ).s.eType == entityType_t::ET_NPC as c_int
                    && !(*targ).client.is_null()
                    && ((*targ).s.eFlags & EF_DEAD) != 0
                {
                    // an NPC that's already dead. Maybe we can cut some more limbs off!
                    if (r#mod == meansOfDeath_t::MOD_SABER as c_int
                        || (r#mod == meansOfDeath_t::MOD_MELEE as c_int
                            && G_HeavyMelee(ctx, ctx.entity_id_of(attacker)) != qfalse))
                        && take > 2
                        && (dflags & DAMAGE_NO_DISMEMBER) == 0
                    {
                        G_CheckForDismemberment(
                            ctx,
                            ctx.entity_id_of(targ).unwrap(),
                            ctx.entity_id_of(attacker),
                            (*targ).pos1,
                            take,
                            (*((*targ).client)).ps.torsoAnim,
                            qtrue,
                        );
                    }
                }

                (*targ).enemy = Some(ent_id(base, attacker));
                if let Some(die_fn) = (*targ).die.get() {
                    crate::ent_fn_enums::dispatch_die(
                        ctx, die_fn, targ, inflictor, attacker, take, r#mod,
                    );
                }
                G_ActivateBehavior(ctx, ctx.entity_id_of(targ), bSet_t::BSET_DEATH as c_int);
                return;
            } else {
                if ctx.world.cvars.g_debugMelee.integer != 0 {
                    // getting hurt makes you let go of the wall
                    if !(*targ).client.is_null()
                        && ((*((*targ).client)).ps.pm_flags & PMF_STUCK_TO_WALL) != 0
                    {
                        crate::w_force::G_LetGoOfWall(ctx, ctx.entity_id_of(targ));
                    }
                }
                if (*targ).pain.is_some() {
                    if (*targ).s.eType != entityType_t::ET_NPC as c_int
                        || r#mod != meansOfDeath_t::MOD_SABER as c_int
                        || take > 1
                    {
                        // don't even notify NPCs of pain if it's just idle saber damage
                        ctx.world.globals.gPainMOD = r#mod;
                        // Raven `if (point) ... else VectorCopy(r.currentOrigin,
                        // gPainPoint)` — zero vector is the NULL sentinel.
                        if point != [0.0, 0.0, 0.0] {
                            crate::q_math::_VectorCopy(point, &mut ctx.world.globals.gPainPoint);
                        } else {
                            crate::q_math::_VectorCopy(
                                (*targ).r.currentOrigin,
                                &mut ctx.world.globals.gPainPoint,
                            );
                        }
                        if let Some(pain_fn) = (*targ).pain.get() {
                            crate::ent_fn_enums::dispatch_pain(ctx, pain_fn, targ, attacker, take);
                        }
                    }
                }
            }

            crate::g_log::G_LogWeaponDamage(ctx, (*attacker).s.number, r#mod, take);
        }
    }
}

/// Raven `G_DamageFromKiller`.
///
/// Source: `oracle/codemp/game/g_combat.c:5717-5758`
pub fn G_DamageFromKiller(
    ctx: &mut GameContext,
    pEnt: Option<EntityId>,
    pVehEnt: Option<EntityId>,
    attacker: Option<EntityId>,
    org: vec3_t,
    damage: c_int,
    dflags: c_int,
    mut r#mod: c_int,
) {
    let mut killer = attacker;
    let mut inflictor = attacker;
    let mut tempInflictor: qboolean = qfalse;
    let (Some(pEnt), Some(pVehEnt)) = (pEnt, pVehEnt) else {
        return;
    };
    // pVehEnt's `.client` is a pool client — deref stays raw (trap 2b).
    let vc = ctx.entity(pVehEnt).client;
    if vc.is_null() {
        return;
    }
    if unsafe { (*vc).ps.otherKiller } < ENTITYNUM_WORLD
        && unsafe { (*vc).ps.otherKillerTime } > ctx.world.level.time
    {
        let potentialKiller = EntityId(unsafe { (*vc).ps.otherKiller } as u32);

        if ctx.entity(potentialKiller).inuse != qfalse {
            // he's valid I guess
            killer = Some(potentialKiller);
            r#mod = unsafe { (*vc).otherKillerMOD };
            inflictor = killer;
            if unsafe { (*vc).otherKillerVehWeapon } > 0 {
                let inflictor_ptr = crate::g_utils::G_Spawn(ctx);
                inflictor = ctx.entity_id_of(inflictor_ptr);
                if let Some(inflictor_id) = inflictor {
                    // fake up the inflictor
                    tempInflictor = qtrue;
                    ctx.entity_mut(inflictor_id).classname =
                        c"vehicle_proj".as_ptr() as *mut c_char;
                    let vw = unsafe { (*vc).otherKillerVehWeapon };
                    ctx.entity_mut(inflictor_id).s.otherEntityNum2 = vw - 1;
                    let wt = unsafe { (*vc).otherKillerWeaponType };
                    ctx.entity_mut(inflictor_id).s.weapon = wt;
                }
            }
        }
    }
    // FIXME: damage hitEnt, some, too?
    if let Some(killer_id) = killer {
        let veh = ctx.entity(killer_id).m_pVehicle;
        if ctx.entity(killer_id).s.eType == entityType_t::ET_NPC as c_int
            && ctx.entity(killer_id).s.NPC_class == class_t::CLASS_VEHICLE as c_int
            && !veh.is_null()
            && !unsafe { (*veh).m_pPilot }.is_null()
        {
            // vehicle-struct/pilot pointers deref raw (trap 2c).
            let pilot_ptr = unsafe { (*veh).m_pPilot } as *mut gentity_t;
            killer = ctx.entity_id_of(pilot_ptr);
        }
    }
    G_Damage(
        ctx,
        Some(pEnt),
        inflictor,
        killer,
        None,
        org,
        damage,
        dflags,
        r#mod,
    );
    if tempInflictor != qfalse {
        crate::g_utils::G_FreeEntity(ctx, inflictor);
    }
}

/// Raven `CanDamage`.
///
/// `origin` is read-only (a trace start point), so it stays by-value.
/// Source: `oracle/codemp/game/g_combat.c:5768-5815`
pub fn CanDamage(ctx: &mut GameContext, targ: EntityId, origin: vec3_t) -> qboolean {
    // `core::mem::zeroed` keeps a tight unsafe scope; the trap Trace macro and
    // entity reads route through the accessor.
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        let mut midpoint: vec3_t = [0.0; 3];
        // Raven `vec3_origin` (zero vector) — passed as the trace bbox.
        let zero: vec3_t = [0.0; 3];

        // use the midpoint of the bounds instead of the origin, because
        // bmodels may have their origin at 0,0,0
        for i in 0..3 {
            midpoint[i] = (ctx.entity(targ).r.absmin[i] + ctx.entity(targ).r.absmax[i]) * 0.5;
        }

        // Inlined `trap_Trace(&tr, origin, vec3_origin, vec3_origin, dest,
        // ENTITYNUM_NONE, MASK_SOLID)` — one per candidate destination.
        macro_rules! trace_to {
            ($dest:expr) => {
                trap::Trace(
                    ctx.engine,
                    GTraceArgs::new(
                        &mut tr as *mut trace_t,
                        &origin as *const vec3_t,
                        &zero as *const vec3_t,
                        &zero as *const vec3_t,
                        &$dest as *const vec3_t,
                        ENTITYNUM_NONE,
                        MASK_SOLID,
                    ),
                )
            };
        }

        let mut dest = midpoint;
        trace_to!(dest);
        if tr.fraction == 1.0 || tr.entityNum as c_int == ctx.entity(targ).s.number {
            return qtrue;
        }

        // this should probably check in the plane of projection, rather than in
        // world coordinate, and also include Z
        dest = midpoint;
        dest[0] += 15.0;
        dest[1] += 15.0;
        trace_to!(dest);
        if tr.fraction == 1.0 {
            return qtrue;
        }

        dest = midpoint;
        dest[0] += 15.0;
        dest[1] -= 15.0;
        trace_to!(dest);
        if tr.fraction == 1.0 {
            return qtrue;
        }

        dest = midpoint;
        dest[0] -= 15.0;
        dest[1] += 15.0;
        trace_to!(dest);
        if tr.fraction == 1.0 {
            return qtrue;
        }

        dest = midpoint;
        dest[0] -= 15.0;
        dest[1] -= 15.0;
        trace_to!(dest);
        if tr.fraction == 1.0 {
            return qtrue;
        }

        qfalse
    }
}

/// Raven `G_RadiusDamage`.
///
/// Source: `oracle/codemp/game/g_combat.c:5823-5943`
pub fn G_RadiusDamage(
    ctx: &mut GameContext,
    origin: vec3_t,
    attacker: Option<EntityId>,
    damage: f32,
    mut radius: f32,
    ignore: Option<EntityId>,
    missile: Option<EntityId>,
    r#mod: c_int,
) -> qboolean {
    let mut entityList: [c_int; MAX_GENTITIES as usize] = [0; MAX_GENTITIES as usize];
    let mut mins: vec3_t = [0.0; 3];
    let mut maxs: vec3_t = [0.0; 3];
    let mut v: vec3_t = [0.0; 3];
    let mut dir: vec3_t = [0.0; 3];
    let mut hitClient: qboolean = qfalse;
    let roastPeople: qboolean = qfalse;

    // (missile burn-mark selection block is #if 0'd out in Raven)

    if radius < 1.0 {
        radius = 1.0;
    }

    for i in 0..3 {
        mins[i] = origin[i] - radius;
        maxs[i] = origin[i] + radius;
    }

    let numListedEntities = trap::EntitiesInBox(
        ctx.engine,
        mp_abi::game::syscalls::G_ENTITIES_IN_BOX::GEntitiesInBoxArgs::new(
            &mins as *const vec3_t,
            &maxs as *const vec3_t,
            entityList.as_mut_ptr(),
            (MAX_GENTITIES) as i32,
        ),
    );

    for e in 0..numListedEntities {
        let ent = EntityId(entityList[e as usize] as u32);

        if Some(ent) == ignore {
            continue;
        }
        if ctx.entity(ent).takedamage == qfalse {
            continue;
        }

        // find the distance from the edge of the bounding box
        for i in 0..3 {
            if origin[i] < ctx.entity(ent).r.absmin[i] {
                v[i] = ctx.entity(ent).r.absmin[i] - origin[i];
            } else if origin[i] > ctx.entity(ent).r.absmax[i] {
                v[i] = origin[i] - ctx.entity(ent).r.absmax[i];
            } else {
                v[i] = 0.0;
            }
        }

        let dist = VectorLength(v);
        if dist >= radius {
            continue;
        }

        // C's `1.0` is a double literal, so the subtract and multiply run in
        // f64 (narrowed at the store); `dist / radius` is still an f32 divide.
        let points = (damage as f64 * (1.0 - (dist / radius) as f64)) as f32;

        if CanDamage(ctx, ent, origin) != qfalse {
            if LogAccuracyHit(ctx, ent, attacker) != qfalse {
                hitClient = qtrue;
            }
            let currentOrigin = ctx.entity(ent).r.currentOrigin;
            _VectorSubtract(currentOrigin, origin, &mut dir);
            // push the center of mass higher than the origin so players get knocked into the air more
            dir[2] += 24.0;
            // Match the oracle's short-circuit ordering: `attacker->m_pVehicle`
            // must only be read after the `attacker` / `m_pVehicle` null guards.
            // The vehicle-struct/pilot pointers deref raw (trap 2c).
            let use_pilot = match attacker {
                Some(attacker_id) => {
                    let veh = ctx.entity(attacker_id).m_pVehicle;
                    ctx.entity(attacker_id).inuse != qfalse
                        && !ctx.entity(attacker_id).client.is_null()
                        && ctx.entity(attacker_id).s.eType == entityType_t::ET_NPC as c_int
                        && ctx.entity(attacker_id).s.NPC_class == class_t::CLASS_VEHICLE as c_int
                        && !veh.is_null()
                        && !unsafe { (*veh).m_pPilot }.is_null()
                }
                None => false,
            };
            if use_pilot {
                let attacker_id = attacker.unwrap();
                let veh = ctx.entity(attacker_id).m_pVehicle;
                let pilot_ptr = unsafe { (*veh).m_pPilot } as *mut gentity_t;
                let pilot = ctx.entity_id_of(pilot_ptr);
                // say my pilot did it.
                G_Damage(
                    ctx,
                    Some(ent),
                    missile,
                    pilot,
                    Some(&mut dir),
                    origin,
                    points as c_int,
                    DAMAGE_RADIUS,
                    r#mod,
                );
            } else {
                G_Damage(
                    ctx,
                    Some(ent),
                    missile,
                    attacker,
                    Some(&mut dir),
                    origin,
                    points as c_int,
                    DAMAGE_RADIUS,
                    r#mod,
                );
            }

            let roast = !ctx.entity(ent).client.is_null()
                && roastPeople != qfalse
                && missile.is_some_and(|missile_id| {
                    VectorCompare(
                        ctx.entity(ent).r.currentOrigin,
                        ctx.entity(missile_id).r.currentOrigin,
                    ) == qfalse
                });
            if roast {
                let missile_id = missile.unwrap();
                // the thing calling this function can create burn marks on people
                let ent_origin = ctx.entity(ent).r.currentOrigin;
                let ev_ptr = G_TempEntity(ctx, ent_origin, entity_event_t::EV_GHOUL2_MARK as c_int);
                let ev_id = ctx.entity_id_of(ev_ptr).unwrap();

                let ent_number = ctx.entity(ent).s.number;
                let missile_origin = ctx.entity(missile_id).r.currentOrigin;
                let evEnt = ctx.entity_mut(ev_id);
                evEnt.s.otherEntityNum = ent_number;
                evEnt.s.weapon = WP_ROCKET_LAUNCHER as c_int;

                evEnt.s.origin = missile_origin;
                evEnt.s.origin2 = ent_origin;

                if missile_origin[2] < ent_origin[2] {
                    evEnt.s.origin2[2] += 8.0;
                } else {
                    evEnt.s.origin2[2] += 24.0;
                }

                evEnt.s.eventParm = 1;
            }
        }
    }

    hitClient
}
